-- MelloUI Languages: Deutsch (deDE). The configurator's and the installer's lines, English -> Deutsch.
-- Written by Tools/languages/languages.py from the addon's English and the translations; a line ending in
-- "-- draft" is a machine draft no translator has checked yet. A line missing here shows in English.
local Lang = MelloUI and MelloUI.Lang
if not (Lang and Lang:Wants("deDE")) then
	return
end
Lang:Add("deDE", {
	-- UIModifications
	["UI Modifications"] = "UI-Anpassungen", -- draft
	["The painted kit reskin, area by area, and the interface's features: buffs and debuffs, error messages, cooldowns, unit frames, chat, tooltips, fonts, dark mode and more. The look is chosen on the Look page and on each element's own page."] = "Der gemalte Kit-Skin, Bereich für Bereich, und die Funktionen der Oberfläche: Stärkungs- und Schwächungszauber, Fehlermeldungen, Abklingzeiten, Einheitenfenster, Chat, Tooltips, Schriften, Dunkelmodus und mehr. Das Aussehen wählst du auf der Seite „Aussehen“ und auf der eigenen Seite jedes Elements.", -- draft
	["The painted reskin, area by area, and the quality-of-life tweaks on nameplates, tooltips, chat and unit frames. Start here."] = "Der gemalte Skin, Bereich für Bereich, und die Komfortanpassungen an Namensplaketten, Tooltips, Chat und Einheitenfenstern. Fang hier an.", -- draft
	["Painted Kit Reskin"] = "Gemalter Kit-Skin", -- draft
	["The game's windows and HUD dressed in the painted kit, and the frame of MelloUI's own windows. Off: the game's windows and HUD keep the game's own art; MelloUI's own parts (the Quest Tracker, the widget column, the reminders, the race bar ...) keep MelloUI's look either way, and every feature keeps working. Switching it on also switches Custom Sounds on, and the first time puts in the Edit Mode layout the reskin is drawn for, fitted to your screen. Switching it off leaves Custom Sounds on."] = "Die Fenster und das HUD des Spiels im gemalten Kit, dazu der Rahmen von MelloUIs eigenen Fenstern. Aus: Die Fenster und das HUD des Spiels behalten die Grafiken des Spiels; MelloUIs eigene Teile (die Questverfolgung, die Widget-Spalte, die Erinnerungen, die Rennleiste ...) behalten so oder so MelloUIs Aussehen, und jede Funktion arbeitet weiter. Beim Einschalten werden auch die Eigenen Sounds eingeschaltet, und beim ersten Mal wird das Layout des Bearbeitungsmodus gesetzt, für das der Skin gezeichnet ist, an deinen Bildschirm angepasst. Beim Ausschalten bleiben die Eigenen Sounds an.", -- draft
	["Preload Artwork"] = "Grafiken vorladen", -- draft
	["Load all of the reskin's artwork during the loading screen, so a window opened for the first time after a reload shows its art at once instead of a moment later. Keeps about 13 MB of artwork in memory for the whole session, including for windows you never open. Off: each piece loads the first time a window needs it."] = "Lädt alle Grafiken des Skins während des Ladebildschirms, damit ein Fenster, das nach einem Neuladen zum ersten Mal öffnet, seine Grafik sofort zeigt statt einen Moment später. Hält etwa 13 MB Grafiken die ganze Sitzung im Speicher, auch für Fenster, die du nie öffnest. Aus: Jedes Teil lädt, wenn ein Fenster es zum ersten Mal braucht.", -- draft
	["Switch every area on"] = "Alle Bereiche einschalten", -- draft
	["Every window and HUD area of the reskin back on, and every feature of UI Modifications that is on by default."] = "Schaltet jeden Fenster- und HUD-Bereich des Skins wieder ein, dazu jede Funktion der UI-Anpassungen, die standardmäßig an ist.", -- draft
	["when nothing is reskinned any more"] = "wenn nichts mehr im Skin ist", -- draft
	["Switch on"] = "Einschalten", -- draft
	["Palette"] = "Palette", -- draft
	["The painted reskin's colours: its art, and MelloUI's own windows and parts while it dresses. Without it MelloUI wears its modern palette, Gilded Slate. Your choice applies at once."] = "Die Farben des gemalten Skins: seine Grafiken und MelloUIs eigene Fenster und Teile, solange er sie einkleidet. Ohne ihn trägt MelloUI seine moderne Palette, Gilded Slate. Deine Wahl gilt sofort.", -- draft
	["Ember"] = "Ember", -- draft
