	["Nameplate Tweaks"] = "Namensplaketten-Anpassungen", -- draft
	["On the game's nameplates: the large crowd-control icon above the name, the quest marker on enemies you still need, the threat line, the combo points on your target's plate, the names' form (Show Names As) and the soft shade behind the names (Name Shade). Off: all six go. Works with or without the reskin."] = "Auf den Namensplaketten des Spiels: das große Kontrollverlust-Symbol über dem Namen, die Questmarkierung auf Gegnern, die du noch brauchst, die Bedrohungslinie, die Combopunkte auf der Plakette deines Ziels, die Form der Namen (Namen anzeigen als) und der weiche Schatten hinter den Namen (Namensschatten). Aus: alle sechs verschwinden. Funktioniert mit oder ohne den Skin.", -- draft
	["Unit Frame Tweaks"] = "Einheitenfenster-Anpassungen", -- draft
	["Name and glow tweaks on the unit frames, the party's levels and the names' soft bands (they step aside where the reskin covers them)."] = "Namens- und Leuchtanpassungen an den Einheitenfenstern, die Stufen der Gruppe und die weichen Streifen der Namen (sie weichen, wo der Skin sie verdeckt).", -- draft
	["Bar Textures"] = "Balkentexturen", -- draft
	["The finish of health and mana bars (flat, smooth, glossy, minimalist) and their colours; the fill under the kit's brackets."] = "Die Oberfläche der Gesundheits- und Manabalken (flach, glatt, glänzend, minimalistisch) und ihre Farben; die Füllung unter den Klammern des Kits.", -- draft
	["Chat Tweaks"] = "Chat-Anpassungen", -- draft
	["Short channel names, class-coloured names, the whisper popup, the chat buttons, smooth scrolling, the names' form (Show Names As), the Background dropdown and the art-hiding switches (which only apply while the chat reskin is off). Off: every one of them goes."] = "Kurze Kanalnamen, Namen in Klassenfarbe, das Flüster-Popup, die Chatknöpfe, sanftes Scrollen, die Form der Namen (Namen anzeigen als), das Menü „Hintergrund“ und die Schalter zum Ausblenden von Grafiken (die nur gelten, solange der Chat-Skin aus ist). Aus: alle verschwinden.", -- draft
	["Tooltip Tweaks"] = "Tooltip-Anpassungen", -- draft
	["Class and reaction colours, the health bar and placement of tooltips. The dark backdrop only applies while the tooltip reskin is off."] = "Klassen- und Reaktionsfarben, der Gesundheitsbalken und die Platzierung der Tooltips. Der dunkle Hintergrund gilt nur, solange der Tooltip-Skin aus ist.", -- draft
	["Custom Fonts"] = "Eigene Schriften", -- draft
	["The fonts and sizes used by the whole interface. Off: the game's own fonts."] = "Die Schriften und Größen der ganzen Oberfläche. Aus: die Schriften des Spiels.", -- draft
	["Dark Mode"] = "Dunkelmodus", -- draft
	["Darkens the painted reskin (its brightness below) and, where the reskin is off, the game's own art of unit frames, bars, nameplates, auras and menus."] = "Dunkelt den gemalten Skin ab (seine Helligkeit unten) und, wo der Skin aus ist, die Grafiken des Spiels an Einheitenfenstern, Leisten, Namensplaketten, Auren und Menüs.", -- draft
	["Vendor Automation"] = "Händler-Automatik", -- draft
	["Repair your gear and sell junk automatically at a merchant."] = "Repariert deine Ausrüstung und verkauft Plunder automatisch bei einem Händler.", -- draft
	["FPS / Latency"] = "FPS / Latenz", -- draft
	["A small coloured FPS and latency readout in the bottom right corner."] = "Eine kleine farbige Anzeige von FPS und Latenz in der unteren rechten Ecke.", -- draft
	-- DarkMode
	["Darkens the Blizzard artwork of unit frames, cast bars, action bars, nameplates, cooldown manager, auras and menu bars."] = "Dunkelt die Blizzard-Grafiken von Einheitenfenstern, Zauberbalken, Aktionsleisten, Namensplaketten, Abklingzeitmanager, Auren und Menüleisten ab.", -- draft
	["Dim the gold and the glare. The interface steps back, the world steps forward."] = "Dämpft das Gold und den Glanz. Die Oberfläche tritt zurück, die Welt tritt hervor.", -- draft
	["Appearance"] = "Aussehen", -- draft
	["Default UI Brightness"] = "Standardhelligkeit der UI", -- draft
	["How bright the game's own artwork is where Dark Mode darkens it (the parts the reskin does not cover, or everything with the reskin off). Lower values are darker. The reskin's own art has Reskin Brightness below."] = "Wie hell die Grafiken des Spiels sind, wo der Dunkelmodus sie abdunkelt (die Teile, die der Skin nicht verdeckt, oder alles mit ausgeschaltetem Skin). Niedrigere Werte sind dunkler. Die Grafiken des Skins haben unten „Helligkeit des Skins“.", -- draft
	["Desaturate"] = "Entsättigen", -- draft
	["Remove the gold and bronze colours so the art becomes grey before it is darkened."] = "Entfernt die Gold- und Bronzetöne, damit die Grafik grau wird, bevor sie abgedunkelt wird.", -- draft
	["Reskin Brightness"] = "Helligkeit des Skins", -- draft
	["How bright the painted reskin is while Dark Mode is on: every kit piece (stone, iron, plates, brackets) is darkened by this much; the red gems keep their colour. The default art above is darkened where the reskin is off."] = "Wie hell der gemalte Skin bei eingeschaltetem Dunkelmodus ist: Jedes Kit-Teil (Stein, Eisen, Schilder, Klammern) wird um so viel abgedunkelt; die roten Edelsteine behalten ihre Farbe. Die Standardgrafik oben wird abgedunkelt, wo der Skin aus ist.", -- draft
	["Components"] = "Bestandteile", -- draft
	["Unit Frames"] = "Einheitenfenster", -- draft
	["Player, target, focus, pet, party, boss and target-of-target frames."] = "Spieler-, Ziel-, Fokus-, Begleiter-, Gruppen-, Boss- und Ziel-des-Ziels-Fenster.", -- draft
	["Cast Bars"] = "Zauberbalken", -- draft
	["Player, pet, target, focus and boss cast bars."] = "Zauberbalken von Spieler, Begleiter, Ziel, Fokus und Bossen.", -- draft
	["Action Bars"] = "Aktionsleisten", -- draft
	["All action bar buttons, the stance bar, pet bar, possess bar and extra action button."] = "Alle Aktionsleistentasten, die Haltungsleiste, die Begleiterleiste, die Besessenheitsleiste und die Extra-Aktionstaste.", -- draft
	["Action Bar End Caps"] = "Endstücke der Aktionsleiste", -- draft
	["Also darken the gryphons / end caps and border art of the main action bar."] = "Dunkelt auch die Greifen / Endstücke und die Randgrafik der Hauptaktionsleiste ab.", -- draft
	["Health bar backgrounds/borders and cast bars on nameplates."] = "Hintergründe und Ränder der Gesundheitsbalken sowie die Zauberbalken auf Namensplaketten.", -- draft
	["Personal Display"] = "Persönliche Anzeige", -- draft
	["The health and power bars shown under your character."] = "Die Gesundheits- und Ressourcenbalken unter deinem Charakter.", -- draft
	["Experience & Reputation Bars"] = "Erfahrungs- & Rufleisten", -- draft
	["Frame, background and segment dividers of the experience, reputation and honor bars."] = "Rahmen, Hintergrund und Segmenttrenner der Erfahrungs-, Ruf- und Ehrenleisten.", -- draft
	["Cooldown Manager"] = "Abklingzeitmanager", -- draft
	["Icon frames and bar backgrounds of the Essential, Utility and Buff cooldown viewers."] = "Symbolrahmen und Balkenhintergründe der Anzeigen für wichtige, nützliche und Stärkungs-Abklingzeiten.", -- draft
	["Micro Menu & Bag Bar"] = "Mikromenü & Taschenleiste", -- draft
	["The menu buttons (character, spellbook, ...) and the bag buttons."] = "Die Menüknöpfe (Charakter, Zauberbuch, ...) und die Taschenknöpfe.", -- draft
	["Minimap ring, zone text header, day/night indicator frame, tracking, calendar, zoom and addon buttons."] = "Ring der Minikarte, Zonentext-Kopf, Rahmen der Tag/Nacht-Anzeige, Aufspüren, Kalender, Zoom- und Addon-Knöpfe.", -- draft
	["Chat Frame"] = "Chatrahmen", -- draft
	["Chat tabs, the chat input box and the chat buttons. Window background colours stay as configured in the chat settings."] = "Chatreiter, das Chat-Eingabefeld und die Chatknöpfe. Die Hintergrundfarben der Fenster bleiben, wie in den Chateinstellungen festgelegt.", -- draft
	["Buffs & Debuffs"] = "Buffs & Debuffs", -- draft
	["Darken the borders of your buff and debuff icons, with a thin dark edge round each icon (0.16.0: the Icon Border switch is part of this). The game's own icons: while Buffs & Debuffs shows MelloUI's rows in their place, there is nothing here to darken (those rows take the Aura Border)."] = "Dunkelt die Ränder deiner Stärkungs- und Schwächungszaubersymbole ab, mit einer dünnen dunklen Kante um jedes Symbol (0.16.0: der Schalter „Symbolrand“ gehört dazu). Die Symbole des Spiels: Solange Buffs & Debuffs MelloUIs Reihen an ihrer Stelle zeigt, gibt es hier nichts abzudunkeln (diese Reihen tragen den Aurenrand).", -- draft
	["Keep Dispel Colours"] = "Bannfarben behalten", -- draft
	["Leave the coloured magic / curse / poison / disease debuff borders untouched: on your buff and debuff icons (Buffs & Debuffs) and on the Cooldown Manager's icons (its Dark Mode)."] = "Lässt die farbigen Ränder von Magie-, Fluch-, Gift- und Krankheitseffekten unberührt: an deinen Stärkungs- und Schwächungszaubersymbolen (Buffs & Debuffs) und an den Symbolen des Abklingzeitmanagers (sein Dunkelmodus).", -- draft
	-- Fonts
	["Fonts"] = "Schriften", -- draft
	["One font per role: interface text, chat and numbers, titles, damage numbers; plus size and outline."] = "Eine Schrift pro Rolle: Oberflächentext, Chat und Zahlen, Titel, Schadenszahlen; dazu Größe und Kontur.", -- draft
	["One font for all of Azeroth. Pick it, scale it, outline it."] = "Eine Schrift für ganz Azeroth. Wähle sie, skaliere sie, umrande sie.", -- draft
	["Font Style"] = "Schriftstil", -- draft
	["A preset: choosing a style changes every font at once -- the titles, the interface text, the chat and numbers, the chat text and the chat on parchment, the sizes back to 100% (each face brings its own size correction) -- each pairing themed with readability first. Fine-tune any of them afterwards (the style then shows Custom). The damage numbers keep their own choice, but for Fredoka's: one face for everything.\nFredoka: MelloUI's own face: Fredoka's round letters for the titles, the text and the damage numbers, to fit MelloUI's icons. The default.\nScriptorium: Cinzel's carved capitals over Alegreya, a warm book face.\nChronicle: Alegreya SC's small capitals over Source Serif 4, the most readable serif.\nOld Tome: IM Fell English's aged print over Spectral.\nWarband: Pirata One's blackletter over Crimson Pro SemiBold: the boldest look.\nClarity: Cinzel titles, Noto Sans everywhere else: the easiest to read at small sizes.\nGothic: Enchanted Land's gothic titles kept, over Alegreya."] = "Eine Vorgabe: Ein Stil ändert alle Schriften zugleich -- die Titel, den Oberflächentext, Chat und Zahlen, den Chattext und den Chat auf Pergament, die Größen zurück auf 100 % (jede Schrift bringt ihre eigene Größenkorrektur mit) --, jede Paarung thematisch und mit Lesbarkeit zuerst. Danach kannst du jede einzeln feinabstimmen (der Stil zeigt dann „Eigene“). Die Schadenszahlen behalten ihre eigene Wahl, außer bei Fredoka: eine Schrift für alles.\nFredoka: MelloUIs eigene Schrift: Fredokas runde Buchstaben für Titel, Text und Schadenszahlen, passend zu MelloUIs Symbolen. Der Standard.\nScriptorium: Cinzels gemeißelte Großbuchstaben über Alegreya, einer warmen Buchschrift.\nChronicle: Alegreya SCs Kapitälchen über Source Serif 4, der lesbarsten Serifenschrift.\nOld Tome: IM Fell Englishs gealterter Druck über Spectral.\nWarband: Pirata Ones Fraktur über Crimson Pro SemiBold: der kräftigste Look.\nClarity: Cinzel-Titel, sonst überall Noto Sans: am leichtesten lesbar in kleinen Größen.\nGothic: Enchanted Lands gotische Titel bleiben, über Alegreya.", -- draft
	["preset: changes every font at once"] = "Vorgabe: ändert alle Schriften zugleich", -- draft
	["Custom"] = "Eigene", -- draft
	["Fredoka"] = "Fredoka", -- draft
	["Scriptorium"] = "Scriptorium", -- draft
	["Chronicle"] = "Chronicle", -- draft
	["Old Tome"] = "Old Tome", -- draft
	["Warband"] = "Warband", -- draft
	["Clarity"] = "Clarity", -- draft
	["Gothic"] = "Gothic", -- draft
	["Interface text (Friz Quadrata)"] = "Oberflächentext (Friz Quadrata)", -- draft
	["Window text, buttons, tooltips, the quest log, nameplate names and the names above characters in the world (those after /reload)."] = "Fenstertext, Schaltflächen, Tooltips, das Questlog, Namen auf Namensplaketten und die Namen über Charakteren in der Welt (diese nach /reload).", -- draft
	["Keep the game's"] = "Die des Spiels behalten", -- draft
	["Friz Quadrata (default)"] = "Friz Quadrata (Standard)", -- draft
	["Chat & numbers (Arial Narrow)"] = "Chat & Zahlen (Arial Narrow)", -- draft
	["The numbers: cooldown counts, stack counts; and the chat windows while Chat text and Interface text both keep the game's. The value text on the unit frames' bars follows the Interface text, the hit numbers on the portraits the Game Numbers Font."] = "Die Zahlen: Abklingzeit- und Stapelzähler; und die Chatfenster, solange Chattext und Oberflächentext beide die des Spiels behalten. Der Wertetext auf den Balken der Einheitenfenster folgt dem Oberflächentext, die Trefferzahlen auf den Porträts der Spielzahlen-Schrift.", -- draft
	["Titles & headers (Morpheus)"] = "Titel & Überschriften (Morpheus)", -- draft
	["Window titles, quest and item names in dialogs, mail and book text, and the kit's title plates and headers while the reskin is on. Enchanted Land unless you choose otherwise. Keep the game's leaves each string in the game's own face: Morpheus where the game uses it, the interface face on the strings that start in it (the Quest Tracker's headers, Combat Text's notices)."] = "Fenstertitel, Quest- und Gegenstandsnamen in Dialogen, Brief- und Buchtext sowie die Titelschilder und Überschriften des Kits, solange der Skin an ist. Enchanted Land, wenn du nichts anderes wählst. „Die des Spiels behalten“ lässt jeden Text in der Schrift des Spiels: Morpheus, wo das Spiel sie nutzt, die Oberflächenschrift bei den Texten, die darin beginnen (die Überschriften der Questverfolgung, die Hinweise des Kampftexts).", -- draft
	["Game Numbers Font (Skurri)"] = "Spielzahlen-Schrift (Skurri)", -- draft
	["The numbers over the enemies: the game's own (after /reload) and Your Damage's (at once); and the hit numbers on the unit frames' portraits. The game's text around you (Combat Text's Game style) and MelloUI's are drawn in the Interface text face."] = "Die Zahlen über den Gegnern: die des Spiels (nach /reload) und die von „Dein Schaden“ (sofort); dazu die Trefferzahlen auf den Porträts der Einheitenfenster. Der Text des Spiels um dich herum (Kampftext im Spielstil) und der von MelloUI stehen in der Oberflächenschrift.", -- draft
	["Chat text"] = "Chattext", -- draft
	["The chat windows' messages, the chat's input box and the whisper windows. The same face as the Interface text unless you choose otherwise (the Chat & numbers face while that is the game's), so the chat follows the Font Styles and your own choice of reading face. The size stays the chat's own (Chat & numbers size)."] = "Die Nachrichten der Chatfenster, das Eingabefeld des Chats und die Flüsterfenster. Dieselbe Schrift wie der Oberflächentext, wenn du nichts anderes wählst (die Schrift für Chat & Zahlen, solange das die des Spiels ist), damit der Chat den Schriftstilen und deiner eigenen Leseschrift folgt. Die Größe bleibt die des Chats (Größe von Chat & Zahlen).", -- draft
	["Same as Interface text"] = "Wie der Oberflächentext", -- draft
	["Chat on parchment"] = "Chat auf Pergament", -- draft
	["The chat windows and whisper windows while they lie on their parchment sheet (Oldschool > Parchment). By default the chat text's face in its semibold cut where it has one, heavier so the dark ink reads on the paper; each Font Style sets that cut of its reading face."] = "Die Chat- und Flüsterfenster, solange sie auf ihrem Pergamentblatt liegen (Oldschool > Pergament). Standardmäßig die Schrift des Chattexts in ihrem halbfetten Schnitt, wo es einen gibt, kräftiger, damit die dunkle Tinte auf dem Papier lesbar ist; jeder Schriftstil setzt diesen Schnitt seiner Leseschrift.", -- draft
	["Chat text, semibold"] = "Chattext, halbfett", -- draft
	["Size and outline"] = "Größe und Kontur", -- draft
	["Interface text size"] = "Größe des Oberflächentexts", -- draft
	["Every font drawn with the interface face, relative to its normal size; a Font Style puts it back to 100% (its faces bring their own correction). Not the text with a size of its own: the Quest Tracker, Combat Text, the chat (Chat & numbers size), FPS / Latency, Cooldown Timers, and the bar values while their size is set."] = "Jede Schrift in der Oberflächenschrift, relativ zu ihrer normalen Größe; ein Schriftstil setzt sie auf 100 % zurück (seine Schriften bringen ihre eigene Korrektur mit). Nicht der Text mit eigener Größe: die Questverfolgung, der Kampftext, der Chat (Größe von Chat & Zahlen), FPS / Latenz, Abklingzeit-Timer und die Balkenwerte, solange ihre Größe gesetzt ist.", -- draft
	["Chat & numbers size"] = "Größe von Chat & Zahlen", -- draft
	["The chat windows (on top of the game's own chat font size) and every number."] = "Die Chatfenster (zusätzlich zur Chat-Schriftgröße des Spiels) und jede Zahl.", -- draft
	["Titles & headers size"] = "Größe von Titeln & Überschriften", -- draft
	["Titles, headers, dialog names, mail and book text, and the kit's title face on the painted plates; a Font Style puts it back to 100% (its faces bring their own correction). Not the Quest Tracker's title and section headers or Combat Text's notices: they have sizes of their own."] = "Titel, Überschriften, Dialognamen, Brief- und Buchtext sowie die Titelschrift des Kits auf den gemalten Schildern; ein Schriftstil setzt sie auf 100 % zurück (seine Schriften bringen ihre eigene Korrektur mit). Nicht die Titel- und Abschnittsüberschriften der Questverfolgung oder die Hinweise des Kampftexts: Sie haben eigene Größen.", -- draft
	["Chat on parchment size"] = "Größe des Chats auf Pergament", -- draft
	["The chat and whisper windows' text on their parchment sheet, relative to the chat's own size."] = "Der Text der Chat- und Flüsterfenster auf ihrem Pergamentblatt, relativ zur eigenen Größe des Chats.", -- draft
	["Outline"] = "Kontur", -- draft
	["Force an outline on every light-coloured font. Dark text on parchment (quests, spellbook, dialogs) keeps its original look. MelloUI's own text in the world (notices, combat text, Gains lines) takes its outline from Notices: Outlined Text; this sets only how thick it is."] = "Erzwingt eine Kontur auf jeder hellen Schrift. Dunkler Text auf Pergament (Quests, Zauberbuch, Dialoge) behält sein ursprüngliches Aussehen. MelloUIs eigener Text in der Welt (Hinweise, Kampftext, Gewinnzeilen) nimmt seine Kontur von Hinweise: Umrandeter Text; dies legt nur fest, wie dick sie ist.", -- draft
	["Keep original"] = "Original behalten", -- draft
	["Thin outline"] = "Dünne Kontur", -- draft
	["Thick outline"] = "Dicke Kontur", -- draft
	-- ClassIcons
	["Class Icons"] = "Klassensymbole", -- draft
	["High resolution painted class medallions in place of the default class icons, and on player portraits."] = "Hochaufgelöste gemalte Klassenmedaillons statt der Standard-Klassensymbole, auch auf Spielerporträts.", -- draft
	["Painted medallions for every class, on the character sheet and on every portrait."] = "Gemalte Medaillons für jede Klasse, im Charakterfenster und auf jedem Porträt.", -- draft
	["The painted class medallions in place of the game's class icons and on player portraits."] = "Die gemalten Klassenmedaillons anstelle der Klassensymbole des Spiels und auf Spielerporträts.", -- draft
	["Player Portraits"] = "Spielerporträts", -- draft
	["Replace player portraits (yourself, target, focus, party) with the player's class medallion. NPC portraits are never touched."] = "Ersetzt Spielerporträts (du selbst, Ziel, Fokus, Gruppe) durch das Klassenmedaillon des Spielers. Porträts von NPCs bleiben immer unberührt.", -- draft
	-- BarTextures
	["Change the fill texture of health, power, nameplate, experience, reputation, honor and cast bars."] = "Ändert die Füllung von Gesundheits-, Ressourcen-, Namensplaketten-, Erfahrungs-, Ruf-, Ehren- und Zauberbalken.", -- draft
	["Health and mana bars in the finish you like: flat, smooth, glossy or minimalist."] = "Gesundheits- und Manabalken in der Oberfläche, die dir gefällt: flach, glatt, glänzend oder minimalistisch.", -- draft
	["Texture"] = "Textur", -- draft
	["Bar Texture"] = "Balkentextur", -- draft
	["Fill texture for every bar whose own Bar Texture is Shared (each sits with its bars, on their own page). Custom files go into MelloUI\\Media\\Textures and are listed in Media\\CustomTextures.lua."] = "Die Füllung für jeden Balken, dessen eigene Balkentextur „Gemeinsam“ ist (jede steht bei ihren Balken, auf deren eigener Seite). Eigene Dateien kommen nach MelloUI\\Media\\Textures und werden in Media\\CustomTextures.lua aufgeführt.", -- draft
	["Default (Blizzard)"] = "Standard (Blizzard)", -- draft
	["Flat"] = "Flach", -- draft
	["Smooth"] = "Glatt", -- draft
	["Gloss"] = "Glanz", -- draft
	["Minimalist"] = "Minimalistisch", -- draft
	["Blizzard Classic"] = "Blizzard Klassisch", -- draft
	["Blizzard Raid"] = "Blizzard Schlachtzug", -- draft
	["Health Bar Colour"] = "Farbe der Gesundheitsbalken", -- draft
	["Colour of the health bars: the unit frames', the nameplates' and your party and raid frames' (Group Frames). Blizzard bakes the green into its artwork, so the module has to colour flat textures itself. By health shades the bar from your full health colour through the half one to the low one, and keeps doing so in combat. My Colour is one colour of yours. An NPC's nameplate keeps the game's own colour (its reaction and threat) with every choice but By health. On the party and raid frames Class and Class / reaction are the class colour."] = "Die Farbe der Gesundheitsbalken: die der Einheitenfenster, der Namensplaketten und deiner Gruppen- und Schlachtzugsfenster (Gruppenfenster). Blizzard backt das Grün in seine Grafik, deshalb muss das Modul flache Texturen selbst einfärben. „Nach Gesundheit“ tönt den Balken von deiner Farbe für volle Gesundheit über die halbe bis zur niedrigen und tut das auch im Kampf. „Meine Farbe“ ist eine Farbe deiner Wahl. Die Namensplakette eines NPCs behält bei jeder Wahl außer „Nach Gesundheit“ die Farbe des Spiels (seine Reaktion und Bedrohung). Auf den Gruppen- und Schlachtzugsfenstern sind „Klasse“ und „Klasse / Reaktion“ die Klassenfarbe.", -- draft
	["Green (Blizzard)"] = "Grün (Blizzard)", -- draft
	["Class colour for players"] = "Klassenfarbe für Spieler", -- draft
	["Class (players) / reaction (NPCs)"] = "Klasse (Spieler) / Reaktion (NPCs)", -- draft
	["By health (your three colours)"] = "Nach Gesundheit (deine drei Farben)", -- draft
	["My Colour"] = "Meine Farbe", -- draft
	["My Health Colour"] = "Meine Gesundheitsfarbe", -- draft
	["The health bars' colour with My Colour."] = "Die Farbe der Gesundheitsbalken mit „Meine Farbe“.", -- draft
	["Full Health Colour"] = "Farbe bei voller Gesundheit", -- draft
	["By health: the colour at full health."] = "Nach Gesundheit: die Farbe bei voller Gesundheit.", -- draft
	["Half Health Colour"] = "Farbe bei halber Gesundheit", -- draft
	["By health: the colour at half health."] = "Nach Gesundheit: die Farbe bei halber Gesundheit.", -- draft
	["Low Health Colour"] = "Farbe bei niedriger Gesundheit", -- draft
	["By health: the colour near death."] = "Nach Gesundheit: die Farbe kurz vor dem Tod.", -- draft
	["Colour Overrides Threat"] = "Farbe vor Bedrohung", -- draft
	["The chosen health bar colour wins over the game's own recolouring of health bars (the aggro / threat display on nameplates and unit frames): whenever the game sets its colour, yours is put back. Off: the game's threat colours show."] = "Die gewählte Farbe der Gesundheitsbalken setzt sich gegen das Umfärben der Gesundheitsbalken durch das Spiel durch (die Aggro- / Bedrohungsanzeige auf Namensplaketten und Einheitenfenstern): Sobald das Spiel seine Farbe setzt, wird deine wiederhergestellt. Aus: Die Bedrohungsfarben des Spiels erscheinen.", -- draft
	["Execute Range"] = "Hinrichtungsbereich", -- draft
	["An enemy's health bar turns purple once its health is below the percentage set here, on the target, focus, target-of-target and boss frames and on nameplates, so you see when finishing moves can be used. Works in combat, when the game hides the exact health, and with every health bar colour."] = "Der Gesundheitsbalken eines Gegners wird lila, sobald seine Gesundheit unter dem hier eingestellten Prozentsatz liegt, auf den Fenstern von Ziel, Fokus, Ziel des Ziels und Bossen sowie auf Namensplaketten, damit du siehst, wann Finishing-Moves möglich sind. Funktioniert im Kampf, wenn das Spiel die genaue Gesundheit verbirgt, und mit jeder Farbe der Gesundheitsbalken.", -- draft
	["Execute Below"] = "Hinrichten unter", -- draft
	["The health percentage under which the bar turns purple (20% for most execute abilities, 35% for some)."] = "Der Gesundheitsprozentsatz, unter dem der Balken lila wird (20 % für die meisten Hinrichtungsfähigkeiten, 35 % für manche).", -- draft
	["Apply To"] = "Anwenden auf", -- draft
	["The fill of the health and power bars of the player, target, focus, pet, party, boss and target-of-target frames: Shared (the Look page's Bar Texture), the game's own art, or a picture of their own."] = "Die Füllung der Gesundheits- und Ressourcenbalken der Fenster von Spieler, Ziel, Fokus, Begleiter, Gruppe, Bossen und Ziel des Ziels: Gemeinsam (die Balkentextur der Seite „Aussehen“), die Grafik des Spiels oder ein eigenes Bild.", -- draft
	["Shared (Look's Bar Texture)"] = "Gemeinsam (Aussehen)", -- draft
	["The game's"] = "Die des Spiels", -- draft
	["Raid Frames"] = "Schlachtzugsfenster", -- draft
	["The fill of MelloUI's party and raid frames and the game's raid-style frames: Shared (the Look page's Bar Texture), Plain (a flat fill; the game's own art on the game's frames), or a picture of their own."] = "Die Füllung von MelloUIs Gruppen- und Schlachtzugsfenstern und den Fenstern des Spiels im Schlachtzugsstil: Gemeinsam (die Balkentextur der Seite „Aussehen“), Schlicht (eine flache Füllung; die Grafik des Spiels auf den Fenstern des Spiels) oder ein eigenes Bild.", -- draft
	["Plain"] = "Schlicht", -- draft
	["The fill of nameplate health and cast bars: Shared (the Look page's Bar Texture), the game's own art, or a picture of their own."] = "Die Füllung der Gesundheits- und Zauberbalken der Namensplaketten: Gemeinsam (die Balkentextur der Seite „Aussehen“), die Grafik des Spiels oder ein eigenes Bild.", -- draft
	["The fill of the Personal Display's health, power and shield bars under your character (and the game's own personal resource display while the Personal Display is off): Shared, Plain, or a picture of their own."] = "Die Füllung der Gesundheits-, Ressourcen- und Schildbalken der Persönlichen Anzeige unter deinem Charakter (und der persönlichen Ressourcenanzeige des Spiels, solange die Persönliche Anzeige aus ist): Gemeinsam, Schlicht oder ein eigenes Bild.", -- draft
	["The fill of the experience, reputation and honor bars, and the damage meter's race bar and Fight History's bars (Minimalist there on The game's): Shared, the game's own art, or a picture of their own."] = "Die Füllung der Erfahrungs-, Ruf- und Ehrenleisten sowie der Rennleiste der Schadensanzeige und der Balken des Kampfverlaufs (dort Minimalistisch bei „Die des Spiels“): Gemeinsam, die Grafik des Spiels oder ein eigenes Bild.", -- draft
	["The fill of the player, pet, target, focus and boss cast bars, and MelloUI's swing timers (Minimalist there on The game's): Shared, the game's own art, or a picture of their own."] = "Die Füllung der Zauberbalken von Spieler, Begleiter, Ziel, Fokus und Bossen sowie von MelloUIs Swing-Timern (dort Minimalistisch bei „Die des Spiels“): Gemeinsam, die Grafik des Spiels oder ein eigenes Bild.", -- draft
	["Cooldown Manager Bars"] = "Balken des Abklingzeitmanagers", -- draft
	["The fill of the Buff Bar cooldown viewer's bars: Shared, the game's own art, or a picture of their own."] = "Die Füllung der Balken in der Stärkungsleisten-Anzeige der Abklingzeiten: Gemeinsam, die Grafik des Spiels oder ein eigenes Bild.", -- draft
	["Tooltip Health Bar"] = "Gesundheitsbalken im Tooltip", -- draft
	["The fill of the health bar under a unit's tooltip (when Tooltip's Hide Health Bar is off): Shared, the game's own art, or a picture of its own."] = "Die Füllung des Gesundheitsbalkens unter dem Tooltip einer Einheit (wenn „Gesundheitsbalken ausblenden“ des Tooltips aus ist): Gemeinsam, die Grafik des Spiels oder ein eigenes Bild.", -- draft
	-- BarText
	["Bar Text"] = "Balkentext", -- draft
	["Always show health and power values on the player, target and focus frames."] = "Zeigt immer die Gesundheits- und Ressourcenwerte auf den Fenstern von Spieler, Ziel und Fokus.", -- draft
	["Numbers where they belong. Health and power values, always in view."] = "Zahlen, wo sie hingehören. Gesundheits- und Ressourcenwerte, immer im Blick.", -- draft
	["Bar Values"] = "Balkenwerte", -- draft
	["Health and power values always shown on the player, target and focus frames."] = "Gesundheits- und Ressourcenwerte immer auf den Fenstern von Spieler, Ziel und Fokus.", -- draft
	["Frames"] = "Fenster", -- draft
	["Player Frame"] = "Spielerfenster", -- draft
	["Show values on the player frame."] = "Zeigt Werte auf dem Spielerfenster.", -- draft
	["Target Frame"] = "Zielfenster", -- draft
	["Show values on the target frame."] = "Zeigt Werte auf dem Zielfenster.", -- draft
	["Focus Frame"] = "Fokusfenster", -- draft
	["Show values on the focus frame."] = "Zeigt Werte auf dem Fokusfenster.", -- draft
	["Bars"] = "Leisten", -- draft
	["Health Bars"] = "Gesundheitsbalken", -- draft
	["Show the health value."] = "Zeigt den Gesundheitswert.", -- draft
	["Power Bars"] = "Ressourcenbalken", -- draft
	["Show the mana / rage / energy value."] = "Zeigt den Wert für Mana / Wut / Energie.", -- draft
	["Style"] = "Stil", -- draft
	["Format"] = "Format", -- draft
	["How the value is written."] = "Wie der Wert geschrieben wird.", -- draft
	["Short (8.2k)"] = "Kurz (8,2k)", -- draft
	["Full (8,234)"] = "Voll (8.234)", -- draft
	["Percent (82%)"] = "Prozent (82 %)", -- draft
	["Short + Percent (8.2k | 82%)"] = "Kurz + Prozent (8,2k | 82 %)", -- draft
	["Short / Max (8.2k / 10k)"] = "Kurz / Max (8,2k / 10k)", -- draft
	["Full / Max (8,234 / 10,000)"] = "Voll / Max (8.234 / 10.000)", -- draft
	["Short / Max + Percent (8.2k / 10k | 82%)"] = "Kurz / Max + Prozent (8,2k / 10k | 82 %)", -- draft
	["Position"] = "Position", -- draft
	["Where the text sits on the bar."] = "Wo der Text auf dem Balken sitzt.", -- draft
	["Center"] = "Mitte", -- draft
	["Left"] = "Links", -- draft
	["Right"] = "Rechts", -- draft
	["Horizontal Offset"] = "Horizontaler Versatz", -- draft
	["Nudge the text left (negative) or right (positive) from where Blizzard places its own bar text."] = "Verschiebt den Text nach links (negativ) oder rechts (positiv) von dort, wo Blizzard seinen eigenen Balkentext setzt.", -- draft
	["Vertical Offset"] = "Vertikaler Versatz", -- draft
	["Nudge the text down (negative) or up (positive)."] = "Verschiebt den Text nach unten (negativ) oder oben (positiv).", -- draft
	["Font Size"] = "Schriftgröße", -- draft
	["Text size. Default follows the status bar text font of the game (and the Fonts module)."] = "Textgröße. Standard folgt der Statusleisten-Schrift des Spiels (und dem Schriftenmodul).", -- draft
	["Values Font"] = "Schrift der Werte", -- draft
	["The face of the health and power values on the player, target and focus frames. Shared: the Interface text's face (Look > Fonts)."] = "Die Schrift der Gesundheits- und Ressourcenwerte auf den Fenstern von Spieler, Ziel und Fokus. Gemeinsam: die Schrift des Oberflächentexts (Aussehen > Schriften).", -- draft
	["Shared"] = "Gemeinsam", -- draft
	-- CooldownText
	["Cooldown Timers"] = "Abklingzeit-Timer", -- draft
	["Large countdown numbers on action bar cooldowns and nameplate auras, coloured by time left."] = "Große Countdown-Zahlen auf den Abklingzeiten der Aktionsleisten und den Auren der Namensplaketten, gefärbt nach der Restzeit.", -- draft
	["Countdowns on every cooldown, coloured by how long you still have to wait."] = "Countdowns auf jeder Abklingzeit, gefärbt danach, wie lange du noch warten musst.", -- draft
	["Countdown numbers on action bar cooldowns and nameplate auras, coloured by the time left."] = "Countdown-Zahlen auf den Abklingzeiten der Aktionsleisten und den Auren der Namensplaketten, gefärbt nach der Restzeit.", -- draft
	["Show On"] = "Zeigen auf", -- draft
	["Action, pet, stance and flyout buttons."] = "Aktions-, Begleiter-, Haltungs- und Ausklapptasten.", -- draft
	["Nameplate Auras"] = "Auren auf Namensplaketten", -- draft
	["Buff, debuff and crowd control icons on nameplates. While Buffs & Debuffs puts your debuffs on enemy nameplates, those icons are MelloUI's own and show their own time: this switch does not reach them."] = "Symbole für Stärkungs-, Schwächungs- und Kontrollverlusteffekte auf Namensplaketten. Solange Buffs & Debuffs deine Schwächungszauber auf gegnerische Namensplaketten legt, sind diese Symbole MelloUIs eigene und zeigen ihre eigene Zeit: Dieser Schalter erreicht sie nicht.", -- draft
	["Timer"] = "Timer", -- draft
	["Minimum Duration"] = "Mindestdauer", -- draft
	["Cooldowns shorter than this show no text (2 s skips the global cooldown)."] = "Abklingzeiten kürzer als diese zeigen keinen Text (2 s überspringt die globale Abklingzeit).", -- draft
	["Text Size"] = "Textgröße", -- draft
	["Text height relative to the icon size."] = "Texthöhe relativ zur Symbolgröße.", -- draft
	["Show Tenths Below 5s"] = "Zehntel unter 5 s zeigen", -- draft
	["Show 4.3 instead of 5 when the cooldown is about to finish."] = "Zeigt 4.3 statt 5, wenn die Abklingzeit gleich endet.", -- draft
	["Colour And Size By Time Left"] = "Farbe und Größe nach Restzeit", -- draft
	["Red and larger under 5 s (1.3 times the Text Size), yellow under a minute, dim white and smaller for minutes (0.8 times), grey and smaller still for hours (0.75 times). Off: every timer is white at the Text Size."] = "Rot und größer unter 5 s (das 1,3-Fache der Textgröße), gelb unter einer Minute, gedämpftes Weiß und kleiner für Minuten (das 0,8-Fache), grau und noch kleiner für Stunden (das 0,75-Fache). Aus: Jeder Timer ist weiß in der Textgröße.", -- draft
	-- Tweaks
	["Tweaks"] = "Anpassungen", -- draft
	["Hide the micro menu and bag bar, and scale the floating combat text."] = "Blendet das Mikromenü und die Taschenleiste aus und skaliert den schwebenden Kampftext.", -- draft
	["Small knobs with a big effect. Hide what you never click, scale what you never see."] = "Kleine Knöpfe mit großer Wirkung. Blende aus, was du nie anklickst, vergrößere, was du nie siehst.", -- draft
	["Hide Frames"] = "Fenster ausblenden", -- draft
	["Hide Micro Menu"] = "Mikromenü ausblenden", -- draft
	["Hide the row of menu buttons (character, spellbook, talents, ...). Still shown while Edit Mode is open."] = "Blendet die Reihe der Menüknöpfe aus (Charakter, Zauberbuch, Talente, ...). Solange der Bearbeitungsmodus offen ist, weiterhin sichtbar.", -- draft
	["Hide Bag Bar"] = "Taschenleiste ausblenden", -- draft
	["Hide the backpack and bag slot buttons. Still shown while Edit Mode is open. Bags can still be opened with their keybinds."] = "Blendet den Rucksack und die Knöpfe der Taschenplätze aus. Solange der Bearbeitungsmodus offen ist, weiterhin sichtbar. Taschen lassen sich weiter mit ihren Tastenbelegungen öffnen.", -- draft
	["Hide Minimap Coordinates"] = "Koordinaten der Minikarte ausblenden", -- draft
	["Hide the player coordinates the client writes under the minimap."] = "Blendet die Spielerkoordinaten aus, die der Client unter die Minikarte schreibt.", -- draft
	["Bag Slots On Bag Window"] = "Taschenplätze am Taschenfenster", -- draft
	["While the bag bar is hidden, show the bag slots under the open bag window so bags can still be equipped and removed. Works with and without the Combine Bags option."] = "Zeigt, solange die Taschenleiste ausgeblendet ist, die Taschenplätze unter dem offenen Taschenfenster, damit Taschen weiter an- und abgelegt werden können. Funktioniert mit und ohne die Option „Taschen kombinieren“.", -- draft
	["Collapse Arrow"] = "Einklapp-Pfeil", -- draft
	["An arrow beside the backpack folds the bag slots away so only the backpack shows; click it again to bring them back. While you hold an item they come out by themselves, so a new bag can be dropped into a slot. The game remembers which way you left it."] = "Ein Pfeil neben dem Rucksack klappt die Taschenplätze weg, sodass nur der Rucksack zu sehen ist; ein weiterer Klick holt sie zurück. Solange du einen Gegenstand hältst, kommen sie von selbst heraus, damit eine neue Tasche in einen Platz gelegt werden kann. Das Spiel merkt sich, wie du es verlassen hast.", -- draft
	["Chat"] = "Chat", -- draft
	["Chat Notices"] = "Chathinweise", -- draft
	["Lines MelloUI writes to chat on its own: a learned dungeon entrance, settings restored from the backup, hints. Replies to slash commands, and the notices you send to the chat (Send To Chat Instead), always show."] = "Zeilen, die MelloUI von sich aus in den Chat schreibt: ein erlernter Dungeoneingang, aus der Sicherung wiederhergestellte Einstellungen, Tipps. Antworten auf Slash-Befehle und die Hinweise, die du in den Chat schickst („Stattdessen in den Chat“), erscheinen immer.", -- draft
	["Notices"] = "Hinweise", -- draft
	["On-screen Notices"] = "Hinweise auf dem Bildschirm", -- draft
	["One short line in the upper third of the screen when MelloUI has news for you: a route set or finished, a service remembered, a dungeon's quests listed. It fades after a few seconds. Move it in Edit Layout."] = "Eine kurze Zeile im oberen Drittel des Bildschirms, wenn MelloUI Neuigkeiten für dich hat: eine Route gesetzt oder beendet, ein Dienst gemerkt, die Quests eines Dungeons aufgelistet. Sie blendet nach ein paar Sekunden aus. Verschiebe sie unter „Layout bearbeiten“.", -- draft
	["Send To Chat Instead"] = "Stattdessen in den Chat", -- draft
	["Write these lines in the chat instead of showing them on the screen. They show there even while Chat Notices is off."] = "Schreibt diese Zeilen in den Chat, statt sie auf dem Bildschirm zu zeigen. Sie erscheinen dort auch, solange die Chathinweise aus sind.", -- draft
	["Notice Sounds"] = "Hinweistöne", -- draft
	["A short chime with each notice: the map's tracking sound for a new destination (left out while the World Marker's own sound plays for it), a softer one when you arrive."] = "Ein kurzer Klang zu jedem Hinweis: der Verfolgungston der Karte für ein neues Ziel (weggelassen, solange der eigene Ton der Weltmarkierung dafür spielt), ein sanfterer bei der Ankunft.", -- draft
	["Text Shade"] = "Textschatten", -- draft
	["A soft dark shade behind the text MelloUI shows on the world, so it reads on bright ground: the zone name when you enter a new area (with its subzone and PvP lines), the game's messages in the middle of the screen (red errors, yellow quest progress, raid warnings and boss emotes), the Route's World Marker, the names on the unit frames (yours, your pet's, your targets' targets' and the party's) and on the nameplates, and the channel tags and links on the chat's parchment. No outline on the zone name and the messages (Outlined Text adds it back); the game's colours stay. Off: the game's own look, and no shade behind any of them."] = "Ein weicher dunkler Schatten hinter dem Text, den MelloUI in der Welt zeigt, damit er auf hellem Grund lesbar ist: der Zonenname beim Betreten eines neuen Gebiets (mit Unterzone und PvP-Zeilen), die Meldungen des Spiels in der Bildschirmmitte (rote Fehler, gelber Questfortschritt, Schlachtzugswarnungen und Bossemotes), die Weltmarkierung der Route, die Namen auf den Einheitenfenstern (deiner, der deines Begleiters, der Ziele deiner Ziele und der Gruppe) und auf den Namensplaketten sowie die Kanalmarken und Links auf dem Pergament des Chats. Keine Kontur bei Zonenname und Meldungen („Umrandeter Text“ fügt sie wieder hinzu); die Farben des Spiels bleiben. Aus: das Aussehen des Spiels und hinter keinem von ihnen ein Schatten.", -- draft
	["Outlined Text"] = "Umrandeter Text", -- draft
	["Draw the text MelloUI shows on the world with an outline: the on-screen notice's lines, Combat Text's lines and the Gains lines, and, while Text Shade is on, the zone text and the game's messages in the middle of the screen. Off: soft text on a dark shade."] = "Zeichnet den Text, den MelloUI in der Welt zeigt, mit einer Kontur: die Zeilen des Bildschirmhinweises, die Zeilen des Kampftexts und die Gewinnzeilen, und, solange der Textschatten an ist, den Zonentext und die Meldungen des Spiels in der Bildschirmmitte. Aus: weicher Text auf dunklem Schatten.", -- draft
	["Combat Text"] = "Kampftext", -- draft
	["Numbers Over Enemies"] = "Zahlen über Gegnern", -- draft
	["The size of the numbers over the enemies and the ones you heal: the game's own, and Your Damage's when MelloUI draws them (one or the other shows). 1.0 is the game's size."] = "Die Größe der Zahlen über den Gegnern und über denen, die du heilst: die des Spiels und die von „Dein Schaden“, wenn MelloUI sie zeichnet (das eine oder das andere erscheint). 1.0 ist die Größe des Spiels.", -- draft
	["Bar Layout"] = "Leistenlayout", -- draft
	["Which Bar"] = "Welche Leiste", -- draft
	["The bar the rows below set: its rows, icons, icon size and padding, saved into your active Edit Mode layout as Edit Mode saves them, once you let a slider go (out of combat). The game shows them after a reload: type /reload (MelloUI says so once). One of the game's preset layouts is copied first: you are asked once."] = "Die Leiste, die die Zeilen unten einstellen: ihre Reihen, Symbole, Symbolgröße und Abstände, gespeichert in dein aktives Layout des Bearbeitungsmodus, wie der Bearbeitungsmodus sie speichert, sobald du einen Schieberegler loslässt (außerhalb des Kampfes). Das Spiel zeigt sie nach einem Neuladen: Gib /reload ein (MelloUI sagt es einmal). Zuerst wird eines der vorgegebenen Layouts des Spiels kopiert: Du wirst einmal gefragt.", -- draft
	["Action Bar 1"] = "Aktionsleiste 1", -- draft
	["Action Bar 2"] = "Aktionsleiste 2", -- draft
	["Action Bar 3"] = "Aktionsleiste 3", -- draft
	["Action Bar 4"] = "Aktionsleiste 4", -- draft
	["Action Bar 5"] = "Aktionsleiste 5", -- draft
	["Action Bar 6"] = "Aktionsleiste 6", -- draft
	["Action Bar 7"] = "Aktionsleiste 7", -- draft
	["Action Bar 8"] = "Aktionsleiste 8", -- draft
	["Stance Bar"] = "Haltungsleiste", -- draft
	["Pet Bar"] = "Begleiterleiste", -- draft
	["Rows"] = "Reihen", -- draft
	["How many rows the bar's buttons stand in (columns, on a bar stood upright in Edit Mode)."] = "In wie vielen Reihen die Tasten der Leiste stehen (Spalten bei einer Leiste, die im Bearbeitungsmodus hochkant steht).", -- draft
	["Icons"] = "Symbole", -- draft
	["How many of the bar's buttons show."] = "Wie viele Tasten der Leiste erscheinen.", -- draft
	["Icon Size"] = "Symbolgröße", -- draft
	["The size of the bar's buttons. 100% is the game's own size."] = "Die Größe der Tasten der Leiste. 100 % ist die Größe des Spiels.", -- draft
	["Padding"] = "Abstand", -- draft
	["The room between the bar's buttons."] = "Der Platz zwischen den Tasten der Leiste.", -- draft
	["The Bar's Shape"] = "Die Form der Leiste", -- draft
	["The bar as the rows above lay it out. Saved into your Edit Mode layout when you let a slider go (in a fight, when it ends); the bar itself changes after a reload."] = "Die Leiste, wie die Zeilen oben sie anordnen. Wird in dein Layout des Bearbeitungsmodus gespeichert, wenn du einen Schieberegler loslässt (im Kampf, wenn er endet); die Leiste selbst ändert sich nach einem Neuladen.", -- draft
	["Buff Layout"] = "Aurenlayout", -- draft
	["The size of your buff and debuff icons, in pixels: MelloUI's own rows while Your Buffs And Debuffs shows them, else the game's buff and debuff bars (saved into your Edit Mode layout in its own steps of 3 pixels, shown after a reload; 30 is the game's size)."] = "Die Größe deiner Stärkungs- und Schwächungszaubersymbole in Pixeln: MelloUIs eigene Reihen, solange „Deine Buffs und Debuffs“ sie zeigt, sonst die Stärkungs- und Schwächungsleisten des Spiels (in dein Layout des Bearbeitungsmodus gespeichert, in dessen eigenen Schritten von 3 Pixeln, sichtbar nach einem Neuladen; 30 ist die Größe des Spiels).", -- draft
	["Spacing"] = "Abstand", -- draft
	["The room between your buff and debuff icons."] = "Der Platz zwischen deinen Stärkungs- und Schwächungszaubersymbolen.", -- draft
	["Per Row"] = "Pro Reihe", -- draft
	["How many buffs stand in a row before the next row starts. Your debuffs start a row of their own (the game's debuff bar takes at most 16 in a row)."] = "Wie viele Stärkungszauber in einer Reihe stehen, bevor die nächste beginnt. Deine Schwächungszauber beginnen eine eigene Reihe (die Schwächungsleiste des Spiels nimmt höchstens 16 pro Reihe).", -- draft
	["Grow"] = "Wachsen", -- draft
	["Which way a row of buffs grows from the first one."] = "In welche Richtung eine Reihe Stärkungszauber vom ersten aus wächst.", -- draft
	["New Rows"] = "Neue Reihen", -- draft
	["Where the next row of buffs goes: under the first, or over it."] = "Wohin die nächste Reihe Stärkungszauber kommt: unter die erste oder darüber.", -- draft
	["Down"] = "Nach unten", -- draft
	["Up"] = "Nach oben", -- draft
	["Split Stack"] = "Stapel teilen", -- draft
	["Mouse Wheel Amount"] = "Menge per Mausrad", -- draft
	["In the box that splits a stack (Shift-click a stack), the mouse wheel changes the amount: up adds one, down takes one, ten at a time while you hold Shift."] = "Im Feld zum Teilen eines Stapels (Umschalt-Klick auf einen Stapel) ändert das Mausrad die Menge: hoch fügt eins hinzu, runter nimmt eins weg, zehn auf einmal, solange du Umschalt hältst.", -- draft
	["Half Button"] = "Halbieren-Knopf", -- draft
	["A ½ button at the left end of the split box's amount: click it and the amount is half the stack (191 makes 95). Buying in bundles at a merchant, it rounds down to whole bundles."] = "Ein ½-Knopf am linken Ende der Menge im Teilen-Feld: Ein Klick setzt die Menge auf den halben Stapel (191 ergibt 95). Beim Kauf in Bündeln bei einem Händler wird auf ganze Bündel abgerundet.", -- draft
	["Item Slots"] = "Gegenstandsplätze", -- draft
	["Quality Gems"] = "Qualitätsedelsteine", -- draft
	["A small gem in the top-left corner of every item in your bags, the bank and the guild bank, in the colour of the item's quality: grey for junk, white for common, then green, blue, purple and orange. Junk and better items stand out at a glance. While the game shows its own mark in that corner (the junk coin at a merchant, the upgrade arrow, the exclamation mark on an item that starts a quest, the quality badge on a crafting reagent), the gem moves to the top-right corner. One switch for all three windows."] = "Ein kleiner Edelstein in der oberen linken Ecke jedes Gegenstands in deinen Taschen, der Bank und der Gildenbank, in der Farbe der Qualität des Gegenstands: grau für Plunder, weiß für gewöhnlich, dann grün, blau, lila und orange. Plunder und bessere Gegenstände fallen auf einen Blick auf. Solange das Spiel in dieser Ecke sein eigenes Zeichen zeigt (die Plundermünze beim Händler, den Verbesserungspfeil, das Ausrufezeichen auf einem Gegenstand, der eine Quest beginnt, das Qualitätsabzeichen auf einem Reagenz), wandert der Edelstein in die obere rechte Ecke. Ein Schalter für alle drei Fenster.", -- draft
	["Grey Out Junk"] = "Plunder ausgrauen", -- draft
	["Junk (grey quality) items show grey in your bags, the bank and the guild bank, so they stand apart from what you keep. One switch for all three windows."] = "Plunder (graue Qualität) erscheint in deinen Taschen, der Bank und der Gildenbank grau, damit er sich von dem abhebt, was du behältst. Ein Schalter für alle drei Fenster.", -- draft
	["Level Up"] = "Stufenaufstieg", -- draft
	["When you gain a level, a light runs along the experience bar and the on-screen notice says your new level and, with the Quest List, how many quests it opened in your zone (their givers pop onto the world map the next time it shows them). With the painted reskin, the number in your player frame's level circle also turns over with a ring of light. Not with Reduce Motion: then only the notice."] = "Wenn du eine Stufe aufsteigst, läuft ein Licht die Erfahrungsleiste entlang, und der Bildschirmhinweis nennt deine neue Stufe und, mit der Questliste, wie viele Quests sie in deiner Zone geöffnet hat (ihre Questgeber erscheinen auf der Weltkarte, wenn sie sie das nächste Mal zeigt). Mit dem gemalten Skin dreht sich auch die Zahl im Stufenkreis deines Spielerfensters mit einem Lichtring weiter. Nicht mit „Bewegung reduzieren“: dann nur der Hinweis.", -- draft
	["XP Gain"] = "Erfahrungsgewinn", -- draft
	["When you gain experience, the stretch of the experience bar just gained lights up while a light runs along it to the new end. Not with Reduce Motion."] = "Wenn du Erfahrung bekommst, leuchtet das eben gewonnene Stück der Erfahrungsleiste auf, während ein Licht zum neuen Ende läuft. Nicht mit „Bewegung reduzieren“.", -- draft
	-- Stats
	["Small coloured FPS and latency readout in the bottom right corner."] = "Kleine farbige Anzeige von FPS und Latenz in der unteren rechten Ecke.", -- draft
	["Frames per second and latency in the corner. Blame the server with confidence."] = "Bilder pro Sekunde und Latenz in der Ecke. Gib dem Server mit gutem Gewissen die Schuld.", -- draft
	["Values"] = "Werte", -- draft
	["Show FPS"] = "FPS zeigen", -- draft
	["Frames per second."] = "Bilder pro Sekunde.", -- draft
	["Show Latency"] = "Latenz zeigen", -- draft
	["Home latency in milliseconds."] = "Heimatlatenz in Millisekunden.", -- draft
	["Show World Latency Too"] = "Auch Weltlatenz zeigen", -- draft
	["Also show the world server latency next to the home latency."] = "Zeigt neben der Heimatlatenz auch die Latenz des Weltservers.", -- draft
	["Look"] = "Aussehen", -- draft
	["Distance from the right edge of the screen."] = "Abstand vom rechten Bildschirmrand.", -- draft
	["Distance from the bottom edge of the screen."] = "Abstand vom unteren Bildschirmrand.", -- draft
	["Update Interval"] = "Aktualisierungsintervall", -- draft
	-- Vendor
	["Vendor"] = "Händler", -- draft
	["Automatically repair your gear and sell junk items when visiting a merchant."] = "Repariert deine Ausrüstung automatisch und verkauft Plunder, wenn du einen Händler besuchst.", -- draft
	["Sell the grey, mend the steel. Every merchant visit handled before the window opens."] = "Das Graue verkaufen, den Stahl flicken. Jeder Händlerbesuch erledigt, bevor das Fenster aufgeht.", -- draft
	["Repair"] = "Reparatur", -- draft
	["Auto Repair"] = "Automatisch reparieren", -- draft
	["Repair all equipped and carried items when a merchant that can repair is opened."] = "Repariert alle angelegten und mitgeführten Gegenstände, wenn ein Händler geöffnet wird, der reparieren kann.", -- draft
	["Use Guild Funds"] = "Gildengold verwenden", -- draft
	["Pay repairs from the guild bank when allowed. Falls back to your own gold if the guild cannot cover the cost."] = "Bezahlt Reparaturen aus der Gildenbank, wenn erlaubt. Nimmt dein eigenes Gold, wenn die Gilde die Kosten nicht decken kann.", -- draft
	["Selling"] = "Verkaufen", -- draft
	["Auto Sell Junk"] = "Plunder automatisch verkaufen", -- draft
	["Sell all grey quality items in your bags when a merchant is opened."] = "Verkauft alle Gegenstände grauer Qualität in deinen Taschen, wenn ein Händler geöffnet wird.", -- draft
	["Report In Chat"] = "Im Chat melden", -- draft
	["Print the repair cost, the gold gained from selling junk and what Restock bought for you."] = "Schreibt die Reparaturkosten, das Gold aus dem Plunderverkauf und was Auffüllen für dich gekauft hat.", -- draft
	-- Services
	["Services"] = "Dienste", -- draft
	["Service icons under the minimap that route you to the nearest repair, mailbox, innkeeper, flight master, auction house, bank, trainer, barber or transmogrifier."] = "Dienstsymbole unter der Minikarte, die dich zum nächsten Reparierer, Briefkasten, Gastwirt, Flugmeister, Auktionshaus, zur Bank, zum Lehrer, Barbier oder Transmogrifizierer führen.", -- draft
	["Repair, mailbox, innkeeper, bank... the nearest one is a click under the minimap."] = "Reparatur, Briefkasten, Gastwirt, Bank ... der nächste ist ein Klick unter der Minikarte.", -- draft
	["Icon Bar Under The Minimap"] = "Symbolleiste unter der Minikarte", -- draft
	["Service buttons under the minimap; they move with the minimap in Edit Mode. Groups: one row of group buttons as wide as the map; click one to open its services with their distances, then click a service to route to the nearest one by road. All Buttons: two rows with an icon for every service; click one to route there. Right-click stops the route. A grey button has none known on this continent yet. With the square minimap and \"Merge With Services\" on (the Minimap page, Services), the buttons sit inside the minimap's frame."] = "Dienstknöpfe unter der Minikarte; sie bewegen sich im Bearbeitungsmodus mit der Minikarte. Gruppen: eine Reihe Gruppenknöpfe so breit wie die Karte; ein Klick öffnet ihre Dienste mit ihren Entfernungen, ein Klick auf einen Dienst führt dich über die Straßen zum nächsten. Alle Knöpfe: zwei Reihen mit einem Symbol für jeden Dienst; ein Klick führt dorthin. Rechtsklick beendet die Route. Ein grauer Knopf hat auf diesem Kontinent noch keinen bekannten. Mit der eckigen Minikarte und eingeschaltetem „Mit Diensten verbinden“ (Seite „Minikarte“, Dienste) sitzen die Knöpfe im Rahmen der Minikarte.", -- draft
	["Button Layout"] = "Knopfanordnung", -- draft
	["Groups: one row of buttons as wide as the map (Travel, Trade, Repair, Trainers, Looks, Errands, and AddOns while your addons have minimap buttons). Click a group for a small list of its services, each with the distance to the nearest one; click a service to route there. Repair routes at once. Errands lists your reminders (Restock, Mail, Repair Gear, Trainer) and how each stands; click one to route to the nearest place for it. All Buttons: two rows with an icon for every service."] = "Gruppen: eine Reihe Knöpfe so breit wie die Karte (Reisen, Handel, Reparatur, Lehrer, Aussehen, Besorgungen und Addons, solange deine Addons Minikartenknöpfe haben). Ein Klick auf eine Gruppe zeigt eine kleine Liste ihrer Dienste, jeder mit der Entfernung zum nächsten; ein Klick auf einen Dienst führt dorthin. Reparatur führt sofort hin. Besorgungen listet deine Erinnerungen (Auffüllen, Post, Ausrüstung reparieren, Lehrer) und ihren Stand; ein Klick führt zum nächsten Ort dafür. Alle Knöpfe: zwei Reihen mit einem Symbol für jeden Dienst.", -- draft
	["Groups"] = "Gruppen", -- draft
	["All Buttons"] = "Alle Knöpfe", -- draft
	["AddOns Group"] = "Addon-Gruppe", -- draft
	["Your addons' minimap buttons (Questie and the others that put a round button on the minimap's edge) taken off the minimap and gathered into one more group in the Services row, AddOns: click it for a list of them. A click on an addon there is that addon's own (left, right or middle), and pointing at it shows its own tooltip. Only with Button Layout's Groups. Off: the buttons go back on the minimap."] = "Die Minikartenknöpfe deiner Addons (Questie und die anderen, die einen runden Knopf an den Rand der Minikarte setzen), von der Minikarte genommen und in einer weiteren Gruppe der Dienste-Reihe gesammelt, Addons: ein Klick zeigt eine Liste davon. Ein Klick auf ein Addon dort ist der des Addons selbst (links, rechts oder Mitte), und wenn du darauf zeigst, erscheint sein eigener Tooltip. Nur mit der Knopfanordnung „Gruppen“. Aus: Die Knöpfe kehren an die Minikarte zurück.", -- draft
	["Bar Distance From The Minimap"] = "Abstand der Leiste von der Minikarte", -- draft
	["How far under the minimap the buttons sit. Not used while they are merged into the square minimap's frame."] = "Wie weit unter der Minikarte die Knöpfe sitzen. Nicht benutzt, solange sie im Rahmen der eckigen Minikarte sitzen.", -- draft
	["Round Icons"] = "Runde Symbole", -- draft
	["Show the service icons as round medallions in a round rim instead of squares."] = "Zeigt die Dienstsymbole als runde Medaillons in einem runden Rand statt als Quadrate.", -- draft
	["Trays Slide Out"] = "Ausfahrende Listen", -- draft
	["A group's list slides out from the minimap column like a drawer when you click its button, its rows one after another, and slides back in as it closes. Not with Reduce Motion: then it shows at once."] = "Die Liste einer Gruppe fährt wie eine Schublade aus der Minikarten-Spalte heraus, wenn du ihren Knopf anklickst, ihre Zeilen nacheinander, und fährt beim Schließen wieder ein. Nicht mit „Bewegung reduzieren“: dann erscheint sie sofort.", -- draft
	["Minimap Button"] = "Minikartenknopf", -- draft
	["Also show a round button on the minimap's edge that opens the list of the nearest services; drag it to move it, right-click it to stop the route. /services opens the same list."] = "Zeigt außerdem einen runden Knopf am Rand der Minikarte, der die Liste der nächsten Dienste öffnet; zieh ihn, um ihn zu verschieben, Rechtsklick beendet die Route. /services öffnet dieselbe Liste.", -- draft
	-- Reminders
	["Reminders"] = "Erinnerungen", -- draft
	["A round button by your portrait for errands: supplies low (Restock), new mail, gear to repair, a trainer with something new. Click it to route there. Off, none of the four shows; the Widgets' portrait reminders keep their own switches."] = "Ein runder Knopf an deinem Porträt für Besorgungen: Vorräte knapp (Auffüllen), neue Post, Ausrüstung zu reparieren, ein Lehrer mit etwas Neuem. Ein Klick führt dich hin. Aus: Keine der vier erscheint; die Porträt-Erinnerungen der Widgets behalten ihre eigenen Schalter.", -- draft
	["Supplies, mail, repairs and training: a gentle nudge beside your portrait, never a nag."] = "Vorräte, Post, Reparaturen und Training: ein sanfter Stups neben deinem Porträt, nie ein Nörgeln.", -- draft
	["New Mail"] = "Neue Post", -- draft
	["Remind you when mail is waiting for you. It goes once you open a mailbox, and comes back only for mail that arrives after."] = "Erinnert dich, wenn Post auf dich wartet. Sie verschwindet, sobald du einen Briefkasten öffnest, und kommt nur für Post zurück, die danach ankommt.", -- draft
	["Repair Gear"] = "Ausrüstung reparieren", -- draft
	["Remind you when your gear is wearing out. Broken gear goes to the top of the list."] = "Erinnert dich, wenn deine Ausrüstung verschleißt. Kaputte Ausrüstung steht oben auf der Liste.", -- draft
	["Remind At"] = "Erinnern bei", -- draft
	["Remind you once your most worn piece of gear is down to this much durability."] = "Erinnert dich, sobald dein abgenutztestes Ausrüstungsteil nur noch so viel Haltbarkeit hat.", -- draft
	["Trainer"] = "Lehrer", -- draft
	["Remind you when a trainer has something new for you."] = "Erinnert dich, wenn ein Lehrer etwas Neues für dich hat.", -- draft
	["Class Spells"] = "Klassenzauber", -- draft
	["When you reach a level with new spells at your class trainer. It stays until you have learned them; each visit to your class trainer tells MelloUI when the next ones come, and before your first visit it goes by the levels trainers teach at."] = "Wenn du eine Stufe mit neuen Zaubern bei deinem Klassenlehrer erreichst. Sie bleibt, bis du sie gelernt hast; jeder Besuch bei deinem Klassenlehrer sagt MelloUI, wann die nächsten kommen, und vor deinem ersten Besuch richtet sie sich nach den Stufen, auf denen Lehrer unterrichten.", -- draft
	["Profession Ranks"] = "Berufsränge", -- draft
	["When one of your professions can learn its next rank at a trainer: Journeyman, Expert or Artisan."] = "Wenn einer deiner Berufe bei einem Lehrer seinen nächsten Rang lernen kann: Geselle, Experte oder Fachmann.", -- draft
	["Stay Up In Rest Areas"] = "In Erholungsgebieten bleiben", -- draft
	["In an inn or a city, and in a town like Sentinel Hill, every reminder stays until it is done (a mailbox opened, the spells or the rank learned ...) or you leave; Not now there waits until you next enter one."] = "In einem Gasthaus oder einer Stadt und in einem Ort wie der Späherkuppe bleibt jede Erinnerung, bis sie erledigt ist (ein Briefkasten geöffnet, die Zauber oder der Rang gelernt ...) oder du gehst; „Nicht jetzt“ wartet dort, bis du das nächste Mal einen betrittst.", -- draft
	["Widget"] = "Widget", -- draft
	["Place"] = "Platz", -- draft
	["Where the reminder button sits beside your portrait. With the player frame hidden it keeps a place of its own, which you can move in Edit Layout."] = "Wo der Erinnerungsknopf neben deinem Porträt sitzt. Mit ausgeblendetem Spielerfenster behält er einen eigenen Platz, den du unter „Layout bearbeiten“ verschieben kannst.", -- draft
	["Left of the portrait"] = "Links vom Porträt", -- draft
	["Above the portrait"] = "Über dem Porträt", -- draft
	["Right of the portrait"] = "Rechts vom Porträt", -- draft
	["Glow"] = "Leuchten", -- draft
	["The soft glow around the button: a gentle pulse for a few seconds, then steady; always steady; or none. It brightens when you are close to where the reminder sends you."] = "Das weiche Leuchten um den Knopf: ein sanftes Pulsieren für ein paar Sekunden, dann ruhig; immer ruhig; oder keines. Es wird heller, wenn du nah an dem Ort bist, zu dem die Erinnerung dich schickt.", -- draft
	["Pulse, then steady"] = "Pulsieren, dann ruhig", -- draft
	["Steady"] = "Ruhig", -- draft
	["Show For"] = "Zeigen für", -- draft
	["How long a new reminder stays before it tucks itself away. It stays while your pointer is on it."] = "Wie lange eine neue Erinnerung bleibt, bevor sie sich wegklappt. Sie bleibt, solange dein Mauszeiger darauf ist.", -- draft
	["Lock The Widgets"] = "Widgets sperren", -- draft
	["Keep the widget column (Voice Over, loot rolls, the corpse run and the rest) where it is: Edit Layout shows its plate but does not move it. Voice Over's padlock sets this too."] = "Hält die Widget-Spalte (Voice Over, Beutewürfe, der Leichenlauf und der Rest) an ihrem Platz: „Layout bearbeiten“ zeigt ihr Schild, verschiebt sie aber nicht. Das Vorhängeschloss von Voice Over setzt dies auch.", -- draft
	["Most Widgets Shown"] = "Höchstens gezeigte Widgets", -- draft
	["How many widgets the column shows at once. The rest wait in a slim \"+2 more\" row on top; a click there lists them. Loot rolls, summons, resurrect offers and ready checks always show, and Voice Over keeps the bottom place."] = "Wie viele Widgets die Spalte auf einmal zeigt. Der Rest wartet oben in einer schmalen Zeile „+2 weitere“; ein Klick dort listet sie. Beutewürfe, Beschwörungen, Wiederbelebungsangebote und Bereitschaftschecks erscheinen immer, und Voice Over behält den untersten Platz.", -- draft
	-- Restock
	["Restock"] = "Auffüllen", -- draft
	["Keeps drink, food, ammunition and reagents in your bags: a reminder when one runs low (with Reminders on), and at a shop a list of what to buy, bought only when you click Buy."] = "Hält Getränke, Essen, Munition und Reagenzien in deinen Taschen: eine Erinnerung, wenn etwas knapp wird (mit eingeschalteten Erinnerungen), und bei einem Laden eine Liste, was zu kaufen ist, gekauft erst, wenn du auf „Kaufen“ klickst.", -- draft
	["Water, bread and arrows, topped up before they run out."] = "Wasser, Brot und Pfeile, aufgefüllt, bevor sie ausgehen.", -- draft
	["Remind Below"] = "Erinnern unter", -- draft
	["You are reminded when a line drops below this share of its amount: at 50 %, a line of 20 water reminds you at 9. At a shop it is bought back up to the full amount. The reminder needs Reminders on; the Restock List marks the low lines either way."] = "Du wirst erinnert, wenn eine Zeile unter diesen Anteil ihrer Menge fällt: Bei 50 % erinnert eine Zeile mit 20 Wasser bei 9. Bei einem Laden wird bis zur vollen Menge nachgekauft. Die Erinnerung braucht eingeschaltete Erinnerungen; die Auffüllliste markiert knappe Zeilen so oder so.", -- draft
	["Shopping List At The Shop"] = "Einkaufsliste im Laden", -- draft
	["At a merchant who sells what you are low on, a small list beside the shop window: each item, how many and the price, and the total. Nothing is bought until you click Buy."] = "Bei einem Händler, der verkauft, was dir fehlt, eine kleine Liste neben dem Ladenfenster: jeder Gegenstand, wie viele und der Preis, und die Summe. Nichts wird gekauft, bevor du auf „Kaufen“ klickst.", -- draft
	["Restock List"] = "Auffüllliste", -- draft
	["What to keep in your bags and how many. Each character has its own list; a new one starts with suggestions for its class. Also /restock."] = "Was du in deinen Taschen behalten willst und wie viel. Jeder Charakter hat seine eigene Liste; eine neue beginnt mit Vorschlägen für seine Klasse. Auch /restock.", -- draft
	["Edit"] = "Bearbeiten", -- draft
	-- Widgets
	["Widgets"] = "Widgets", -- draft
	["Small live widgets in one column: loot rolls, the way back to your corpse, timed quests, summons, resurrect offers, ready checks, whispers, your pet, the auction house, crafting batches, profession cooldowns, quest items and a healer drinking. And more reminders by your portrait: bags, talents, Well Fed, weapon poisons and oils, your buffs."] = "Kleine Live-Widgets in einer Spalte: Beutewürfe, der Weg zurück zu deiner Leiche, zeitlich begrenzte Quests, Beschwörungen, Wiederbelebungsangebote, Bereitschaftschecks, Flüstern, dein Begleiter, das Auktionshaus, Herstellungsserien, Berufsabklingzeiten, Questgegenstände und ein trinkender Heiler. Dazu mehr Erinnerungen an deinem Porträt: Taschen, Talente, Satt, Waffengifte und -öle, deine Stärkungszauber.", -- draft
	["What needs you now, in one small column."] = "Was dich jetzt braucht, in einer kleinen Spalte.", -- draft
	["In The Column"] = "In der Spalte", -- draft
	["Loot Rolls"] = "Beutewürfe", -- draft
	["A roll in a group: the item in its quality colour, a ring for the time left, and Need, Greed and Pass on hover. The count is the rolls waiting. The game's own roll window stays out of sight meanwhile (with the Gamepad UI it stays)."] = "Ein Wurf in einer Gruppe: der Gegenstand in seiner Qualitätsfarbe, ein Ring für die Restzeit und Bedarf, Gier und Passen beim Darüberfahren. Die Zahl sind die wartenden Würfe. Das Wurffenster des Spiels bleibt so lange außer Sicht (mit der Controller-Oberfläche bleibt es).", -- draft
	["Corpse Run"] = "Leichenlauf", -- draft
	["As a ghost: how far your body is and which way, and a ring until you can come back. Click it for the way there; at your body, Resurrect. The game's own Resurrect popup is see-through and click-through meanwhile."] = "Als Geist: wie weit dein Körper entfernt ist und in welcher Richtung, und ein Ring, bis du zurückkehren kannst. Ein Klick zeigt den Weg dorthin; bei deinem Körper Wiederbeleben. Das Wiederbeleben-Popup des Spiels ist so lange durchsichtig und klickdurchlässig.", -- draft
	["Timed Quests"] = "Zeitlich begrenzte Quests", -- draft
	["A quest with a time limit: a ring for its whole time and the time left."] = "Eine Quest mit Zeitlimit: ein Ring für ihre ganze Zeit und die Restzeit.", -- draft
	["Summons"] = "Beschwörungen", -- draft
	["Someone summons you: where to, the time left, and Accept or Decline on hover. The game's own popup is see-through and click-through meanwhile."] = "Jemand beschwört dich: wohin, die Restzeit und Annehmen oder Ablehnen beim Darüberfahren. Das Popup des Spiels ist so lange durchsichtig und klickdurchlässig.", -- draft
	["Resurrect Offers"] = "Wiederbelebungsangebote", -- draft
	["Someone offers to resurrect you: the time left, and Accept or Decline on hover. The game's own popup is see-through and click-through meanwhile."] = "Jemand bietet an, dich wiederzubeleben: die Restzeit und Annehmen oder Ablehnen beim Darüberfahren. Das Popup des Spiels ist so lange durchsichtig und klickdurchlässig.", -- draft
	["Ready Checks"] = "Bereitschaftschecks", -- draft
	["The leader's ready check and its time, with Ready and Not Ready on hover (a click on it: Ready). The game's own box stays away meanwhile (with the Gamepad UI it stays); its alert sound and the taskbar flash still come."] = "Der Bereitschaftscheck des Anführers und seine Zeit, mit Bereit und Nicht bereit beim Darüberfahren (ein Klick darauf: Bereit). Das Fenster des Spiels bleibt so lange weg (mit der Controller-Oberfläche bleibt es); sein Warnton und das Blinken der Taskleiste kommen weiterhin.", -- draft
	["Threat"] = "Bedrohung", -- draft
	["In a group fight, only when it matters: close to pulling your target (\"Ease off\") or with it on you (\"Aggro\"), and for a tank the mobs not on you. The ring is your threat against the pull; point at it for the group's threat on your target."] = "In einem Gruppenkampf, nur wenn es zählt: kurz davor, dein Ziel zu ziehen („Langsamer“), oder wenn es auf dir ist („Aggro“), und für einen Tank die Gegner, die nicht auf ihm sind. Der Ring ist deine Bedrohung gegen den Zug; zeig darauf für die Bedrohung der Gruppe auf deinem Ziel.", -- draft
	["Whispers"] = "Flüstern", -- draft
	["A new whisper: the sender in their class colour, the last line and how many are unread. Reply opens their whisper window. Needs Chat's Whisper Popup Window."] = "Ein neues Flüstern: der Absender in seiner Klassenfarbe, die letzte Zeile und wie viele ungelesen sind. „Antworten“ öffnet sein Flüsterfenster. Braucht das Flüster-Popup-Fenster des Chats.", -- draft
	["Hunter Pet"] = "Jägerbegleiter", -- draft
	["Your pet is not happy: its face, a ring for its happiness, and Feed Pet on hover (out of combat)."] = "Dein Begleiter ist nicht zufrieden: sein Gesicht, ein Ring für seine Zufriedenheit und „Tier füttern“ beim Darüberfahren (außerhalb des Kampfes).", -- draft
	["Auction House"] = "Auktionshaus", -- draft
	["Outbid, sold, won and expired at the auction house, in one list. Click it for the way to the nearest mailbox."] = "Überboten, verkauft, gewonnen und abgelaufen im Auktionshaus, in einer Liste. Ein Klick zeigt den Weg zum nächsten Briefkasten.", -- draft
	["Crafting"] = "Herstellung", -- draft
	["A batch you craft: which one of how many, a ring for each item, and Stop on hover."] = "Eine Serie, die du herstellst: welches von wie vielen, ein Ring für jeden Gegenstand und „Stopp“ beim Darüberfahren.", -- draft
	["Profession Cooldowns"] = "Berufsabklingzeiten", -- draft
	["A profession cooldown ready again (a transmute, mooncloth, the salt shaker). MelloUI learns it when you open that profession."] = "Eine Berufsabklingzeit wieder bereit (eine Transmutation, Mondstoff, der Salzstreuer). MelloUI lernt sie, wenn du diesen Beruf öffnest.", -- draft
	["Quest Items"] = "Questgegenstände", -- draft
	["In a quest's objective area, with the quest's item in your bags: the item, a ring for the objective's progress and how many you carry. Click it to use the item (out of combat: it folds away in a fight)."] = "Im Zielgebiet einer Quest, mit dem Gegenstand der Quest in deinen Taschen: der Gegenstand, ein Ring für den Fortschritt des Ziels und wie viele du trägst. Ein Klick benutzt den Gegenstand (außerhalb des Kampfes: im Kampf klappt es weg).", -- draft
	["Healer Drinking"] = "Heiler trinkt", -- draft
	["When you tank a group, between pulls: a healer of your group is drinking, so wait before the next pull. It goes when they stop or a fight starts. The game keeps party mana hidden from addons, so it shows their drinking, not their mana."] = "Wenn du eine Gruppe tankst, zwischen den Zügen: Ein Heiler deiner Gruppe trinkt, also warte vor dem nächsten Zug. Es verschwindet, wenn er aufhört oder ein Kampf beginnt. Das Spiel verbirgt das Mana der Gruppe vor Addons, deshalb zeigt es sein Trinken, nicht sein Mana.", -- draft
	["Rare Alert"] = "Seltenen-Alarm", -- draft
	["A rare or rare elite nearby, seen on the minimap, as a nameplate, as your target or under the mouse: its face, its name and how far it is, glowing as it comes up. Click its face to target it (out of combat); Lead Me There shows the way to where the minimap has it."] = "Ein seltener oder seltener Elitegegner in der Nähe, gesehen auf der Minikarte, als Namensplakette, als dein Ziel oder unter der Maus: sein Gesicht, sein Name und wie weit er weg ist, aufleuchtend, wenn er erscheint. Ein Klick auf sein Gesicht nimmt ihn ins Ziel (außerhalb des Kampfes); „Führ mich hin“ zeigt den Weg dorthin, wo die Minikarte ihn hat.", -- draft
	["Rare Alert Sound"] = "Ton beim Seltenen-Alarm", -- draft
	["Play a sound when a rare is spotted."] = "Spielt einen Ton, wenn ein Seltener entdeckt wird.", -- draft
	["By The Portrait"] = "Am Porträt", -- draft
	["Bags Almost Full"] = "Taschen fast voll", -- draft
	["Remind you when your bags are almost full; it stays, in a fight too, until you make room. Click it for the way to the nearest vendor."] = "Erinnert dich, wenn deine Taschen fast voll sind; es bleibt, auch im Kampf, bis du Platz schaffst. Ein Klick zeigt den Weg zum nächsten Händler.", -- draft
	["Free Slots"] = "Freie Plätze", -- draft
	["Remind you once this many free bag slots or fewer are left."] = "Erinnert dich, sobald nur noch so viele freie Taschenplätze oder weniger übrig sind.", -- draft
	["Talent Points"] = "Talentpunkte", -- draft
	["Remind you when you have talent points to spend."] = "Erinnert dich, wenn du Talentpunkte zu verteilen hast.", -- draft
	["Well Fed Ending"] = "„Satt“ endet", -- draft
	["Remind you when Well Fed has two minutes left."] = "Erinnert dich, wenn „Satt“ noch zwei Minuten hat.", -- draft
	["Weapon Poisons & Oils"] = "Waffengifte & -öle", -- draft
	["Remind you when a poison, an oil or a sharpening stone has run out on a weapon, or has two minutes left, while you carry one to put it back on. It stays until it is back on, in fights too; click it to put it back on (out of combat)."] = "Erinnert dich, wenn ein Gift, ein Öl oder ein Wetzstein auf einer Waffe abgelaufen ist oder noch zwei Minuten hat, solange du eines dabeihast, um es wieder aufzutragen. Es bleibt, bis es wieder drauf ist, auch im Kampf; ein Klick trägt es wieder auf (außerhalb des Kampfes).", -- draft
	["Your Buffs"] = "Deine Stärkungszauber", -- draft
	["Remind you when one of your own buffs is missing on you: Arcane Intellect and a mage's armor, Fortitude, Inner Fire and Divine Spirit, Mark of the Wild, a warlock's armor. Only buffs you can cast. It stays until the buff is back, in fights too (the game hides buffs in a fight, so one lost there shows after it); click it to cast (out of combat)."] = "Erinnert dich, wenn einer deiner eigenen Stärkungszauber auf dir fehlt: Arkane Intelligenz und die Rüstung eines Magiers, Seelenstärke, Inneres Feuer und Göttlicher Willen, Mal der Wildnis, die Rüstung eines Hexenmeisters. Nur Stärkungszauber, die du wirken kannst. Es bleibt, bis der Stärkungszauber wieder da ist, auch im Kampf (das Spiel verbirgt Stärkungszauber im Kampf, also erscheint einer, der dort verloren geht, danach); ein Klick wirkt ihn (außerhalb des Kampfes).", -- draft
	["Your Buffs On The Group"] = "Deine Stärkungszauber auf der Gruppe", -- draft
	["Remind you when people in your group are missing a buff you can cast (Arcane Intellect and Divine Spirit only on those who use mana); point at it for their names. It stays until they have it, in fights too; click it to cast it on them, one by one (out of combat)."] = "Erinnert dich, wenn Leuten in deiner Gruppe ein Stärkungszauber fehlt, den du wirken kannst (Arkane Intelligenz und Göttlicher Willen nur bei denen, die Mana nutzen); zeig darauf für ihre Namen. Es bleibt, bis sie ihn haben, auch im Kampf; ein Klick wirkt ihn auf sie, einen nach dem anderen (außerhalb des Kampfes).", -- draft
	-- Discard
	["Discard"] = "Wegwerfen", -- draft
	["A button on the bag and loot windows that throws away your cheapest grey or white junk to free a slot (sells it at a vendor)."] = "Ein Knopf an den Taschen- und Beutefenstern, der deinen billigsten grauen oder weißen Plunder wegwirft, um einen Platz frei zu machen (bei einem Händler verkauft er ihn).", -- draft
	["Full bags? The cheapest junk makes room, never anything worth keeping."] = "Taschen voll? Der billigste Plunder macht Platz, nie etwas, das es wert ist, behalten zu werden.", -- draft
	["Discard Button"] = "Wegwerfen-Knopf", -- draft
	["A button on the bag window that frees a slot: it throws away the grey or white junk item worth least (at a vendor it sells it). Never food, drink, potions, scrolls, conjured items, crafting materials, quest items, reagents, ammunition, keys, white gear or anything on your Restock list. A white item asks first."] = "Ein Knopf am Taschenfenster, der einen Platz frei macht: Er wirft den grauen oder weißen Plundergegenstand mit dem geringsten Wert weg (bei einem Händler verkauft er ihn). Nie Essen, Getränke, Tränke, Schriftrollen, herbeigezauberte Gegenstände, Handwerksmaterialien, Questgegenstände, Reagenzien, Munition, Schlüssel, weiße Ausrüstung oder irgendetwas auf deiner Auffüllliste. Ein weißer Gegenstand fragt zuerst.", -- draft
	["Discard Button On Loot"] = "Wegwerfen-Knopf bei Beute", -- draft
	["The same button on the loot window. It frees a slot only when something you are looting is worth more than what it would throw away."] = "Derselbe Knopf am Beutefenster. Er macht nur dann einen Platz frei, wenn etwas, das du plünderst, mehr wert ist als das, was er wegwerfen würde.", -- draft
	["Never Throw Away Items Worth"] = "Nie wegwerfen ab einem Wert von", -- draft
	["In silver: a stack worth this or more is never thrown away (selling it at a vendor still is). 100 silver = 1 gold."] = "In Silber: Ein Stapel mit diesem Wert oder mehr wird nie weggeworfen (beim Händler wird er weiterhin verkauft). 100 Silber = 1 Gold.", -- draft
	-- Gains
	["Gains"] = "Gewinne", -- draft
	["Short lines beside your character show what you just gained: a skill point, the items you loot or receive, and what you buy. You can move them in Edit Layout."] = "Kurze Zeilen neben deinem Charakter zeigen, was du gerade bekommen hast: einen Fertigkeitspunkt, die Gegenstände, die du plünderst oder erhältst, und was du kaufst. Du kannst sie unter „Layout bearbeiten“ verschieben.", -- draft
	["Every skill point and every new item, told softly beside your character, then gone."] = "Jeder Fertigkeitspunkt und jeder neue Gegenstand, leise neben deinem Charakter erzählt, dann weg.", -- draft
	["Show"] = "Zeigen", -- draft
	["Skill Ups"] = "Fertigkeitssteigerungen", -- draft
	["A line when one of your skills goes up: weapon skills, Defense, professions, secondary skills and languages."] = "Eine Zeile, wenn eine deiner Fertigkeiten steigt: Waffenfertigkeiten, Verteidigung, Berufe, Nebenfertigkeiten und Sprachen.", -- draft
	["Show Skill Values"] = "Fertigkeitswerte zeigen", -- draft
	["The skill's new value and its cap after its name, such as 57 / 80."] = "Der neue Wert der Fertigkeit und ihre Obergrenze nach ihrem Namen, etwa 57 / 80.", -- draft
	["Looted & Received Items"] = "Geplünderte & erhaltene Gegenstände", -- draft
	["A line for each item that comes into your bags: loot, quest rewards, crafted items, mail and trades. Moving items between your bags, the bank and your gear never counts."] = "Eine Zeile für jeden Gegenstand, der in deine Taschen kommt: Beute, Questbelohnungen, hergestellte Gegenstände, Post und Handel. Gegenstände zwischen Taschen, Bank und Ausrüstung zu verschieben zählt nie.", -- draft
	["Bought Items"] = "Gekaufte Gegenstände", -- draft
	["A line for what you buy from a merchant, buybacks too, marked as bought."] = "Eine Zeile für das, was du bei einem Händler kaufst, Rückkäufe auch, als gekauft markiert.", -- draft
	["Junk Items"] = "Plundergegenstände", -- draft
	["Also show junk (grey) items. Off: they are left out."] = "Zeigt auch Plunder (graue Gegenstände). Aus: Sie werden weggelassen.", -- draft
	["Money"] = "Geld", -- draft
	["A line when your money goes up: loot, quest rewards, sales, mail and trades, with the game's coins. Several gains in a row add up on one line. Spending makes no line."] = "Eine Zeile, wenn dein Geld mehr wird: Beute, Questbelohnungen, Verkäufe, Post und Handel, mit den Münzen des Spiels. Mehrere Gewinne hintereinander addieren sich in einer Zeile. Ausgaben ergeben keine Zeile.", -- draft
	["Currencies"] = "Währungen", -- draft
	["A line for the other currencies you gain (honor, tokens, marks), with the currency's own icon."] = "Eine Zeile für die anderen Währungen, die du bekommst (Ehre, Abzeichen, Marken), mit dem eigenen Symbol der Währung.", -- draft
	["Item Names In Quality Colour"] = "Gegenstandsnamen in Qualitätsfarbe", -- draft
	["Item names in their quality colour (green, blue, purple) beside the quality gem. Blue and purple read less well over bright ground. Off: the names in the text colour."] = "Gegenstandsnamen in ihrer Qualitätsfarbe (grün, blau, lila) neben dem Qualitätsedelstein. Blau und Lila lesen sich über hellem Grund schlechter. Aus: die Namen in der Textfarbe.", -- draft
	["Lines"] = "Zeilen", -- draft
	["How long each line stays before it fades. Gaining the same skill or item again adds to its line and starts it over."] = "Wie lange jede Zeile bleibt, bevor sie ausblendet. Dieselbe Fertigkeit oder denselben Gegenstand erneut zu bekommen, ergänzt ihre Zeile und startet sie neu.", -- draft
	-- Meter
	["Damage Meter"] = "Schadensanzeige", -- draft
	["MelloUI's damage meter in place of the game's: three numbers by every frame (this fight, this run, healing), a race bar for the group in a fight, a summary after it and a Fight History window. The game's own damage meter is switched off while it is on, and comes back as you had it when it is off."] = "MelloUIs Schadensanzeige anstelle der des Spiels: drei Zahlen an jedem Fenster (dieser Kampf, dieser Lauf, Heilung), eine Rennleiste für die Gruppe im Kampf, eine Zusammenfassung danach und ein Fenster „Kampfverlauf“. Die Schadensanzeige des Spiels ist ausgeschaltet, solange sie an ist, und kommt so zurück, wie du sie hattest, wenn sie aus ist.", -- draft
	["How the fight went, where you already look."] = "Wie der Kampf lief, dort, wo du ohnehin hinschaust.", -- draft
	["Your Values"] = "Deine Werte", -- draft
	["Three numbers on top of your frame: the sword this fight's damage per second, the hourglass this run's, the cross your healing per second. Live in a fight, the last fight's after it. Move them in Edit Layout (Your Values)."] = "Drei Zahlen oben auf deinem Fenster: das Schwert für den Schaden pro Sekunde dieses Kampfes, die Sanduhr für den dieses Laufs, das Kreuz für deine Heilung pro Sekunde. Live im Kampf, danach die des letzten Kampfes. Verschiebe sie unter „Layout bearbeiten“ (Deine Werte).", -- draft
	["Party Values"] = "Werte der Gruppe", -- draft
	["The same three numbers on top of each party frame. To make room, the game's own Show Party Pets setting is switched on while this is on (the party frames stand a little further apart, and party pets show under them); your own setting comes back when it is off. With raid-style party frames: On Raid-Style Frames."] = "Dieselben drei Zahlen oben auf jedem Gruppenfenster. Um Platz zu schaffen, wird die Einstellung „Gruppenbegleiter anzeigen“ des Spiels eingeschaltet, solange dies an ist (die Gruppenfenster stehen etwas weiter auseinander, und Gruppenbegleiter erscheinen darunter); deine eigene Einstellung kehrt zurück, wenn es aus ist. Mit Gruppenfenstern im Schlachtzugsstil: „Auf Fenstern im Schlachtzugsstil“.", -- draft
	["On Raid-Style Frames"] = "Auf Fenstern im Schlachtzugsstil", -- draft
	["A small DPS or healing number on the right of each raid-style or raid frame, beside the health. In a fight, players MelloUI cannot tell apart stay empty until it ends. Point at a frame for all three numbers."] = "Eine kleine DPS- oder Heilungszahl rechts auf jedem Fenster im Schlachtzugsstil oder Schlachtzugsfenster, neben der Gesundheit. Im Kampf bleiben Spieler, die MelloUI nicht auseinanderhalten kann, leer, bis er endet. Zeig auf ein Fenster für alle drei Zahlen.", -- draft
	["Race Bar"] = "Rennleiste", -- draft
	["In a fight, one line for the group: the top player at its right end with their value, everyone else a class icon at their share of the top, you the bigger icon with the line filled up to you in your class colour. It fades in when the fight starts and out when it ends. The pointer on it lists everyone. Move it in Edit Layout."] = "Im Kampf eine Zeile für die Gruppe: der beste Spieler an ihrem rechten Ende mit seinem Wert, alle anderen ein Klassensymbol an ihrem Anteil am Besten, du das größere Symbol mit der Linie bis zu dir in deiner Klassenfarbe gefüllt. Sie blendet ein, wenn der Kampf beginnt, und aus, wenn er endet. Der Mauszeiger darauf listet alle. Verschiebe sie unter „Layout bearbeiten“.", -- draft
	["Race Bar Shows"] = "Die Rennleiste zeigt", -- draft
	["What the race bar races. Auto: healing while your group role is healer, else damage."] = "Was die Rennleiste vergleicht. Automatisch: Heilung, solange deine Gruppenrolle Heiler ist, sonst Schaden.", -- draft
	["Auto"] = "Automatisch", -- draft
	["Damage"] = "Schaden", -- draft
	["Healing"] = "Heilung", -- draft
	["Race Bar Pins"] = "Plätze auf der Rennleiste", -- draft
	["The most players on the race bar: the best ones, and always you."] = "Die meisten Spieler auf der Rennleiste: die besten und immer du.", -- draft
	["Race Bar Width"] = "Breite der Rennleiste", -- draft
	["How wide the race bar is. Also in Edit Layout: right-click the race bar."] = "Wie breit die Rennleiste ist. Auch unter „Layout bearbeiten“: Rechtsklick auf die Rennleiste.", -- draft
	["Race Bar Thickness"] = "Dicke der Rennleiste", -- draft
	["How thick your share is on the race bar's line (its pins and labels keep their size). Also in Edit Layout: right-click the race bar."] = "Wie dick dein Anteil auf der Linie der Rennleiste ist (ihre Markierungen und Beschriftungen behalten ihre Größe). Auch unter „Layout bearbeiten“: Rechtsklick auf die Rennleiste.", -- draft
	["Fight Summary"] = "Kampfzusammenfassung", -- draft
	["After a fight, for a few seconds in the widget column (longer while you point at it): won or lost and its length, your damage, DPS and rank, the ring your share of the group. The pointer on it shows the top five; a click opens the fight in the Fight History."] = "Nach einem Kampf für ein paar Sekunden in der Widget-Spalte (länger, solange du darauf zeigst): gewonnen oder verloren und seine Dauer, dein Schaden, deine DPS und dein Rang, der Ring als dein Anteil an der Gruppe. Der Mauszeiger darauf zeigt die besten fünf; ein Klick öffnet den Kampf im Kampfverlauf.", -- draft
	["Fight History"] = "Kampfverlauf", -- draft
	["The Fight History window: every fight of this session, grouped by run, with the damage, healing and your spells of each. It opens from its button in the chat's button column and from the summary. It takes the place of the game's meter windows."] = "Das Fenster „Kampfverlauf“: jeder Kampf dieser Sitzung, nach Lauf gruppiert, mit Schaden, Heilung und deinen Zaubern in jedem. Es öffnet sich über seinen Knopf in der Knopfspalte des Chats und über die Zusammenfassung. Es nimmt den Platz der Anzeigefenster des Spiels ein.", -- draft
	["Fights Kept"] = "Gemerkte Kämpfe", -- draft
	["How many fights the history keeps, the oldest dropped first. Kept over a /reload; a new login starts it empty."] = "Wie viele Kämpfe der Verlauf behält, der älteste fällt zuerst weg. Bleibt über ein /reload erhalten; eine neue Anmeldung beginnt leer.", -- draft
	-- SwingTimers
	["Swing Timers"] = "Swing-Timer", -- draft
	["A shot bar and a melee bar in MelloUI's look in place of the game's swing timers: each swing and shot counted down beside your weapon's icon, the off hand under the main hand, a wand's shots on the melee bar. The game's own swing timers are switched off while this is on, and come back as you had them when it is off. While the Personal Display shows your swing on its rails (Swing On The Rails), these bars step aside."] = "Eine Schussleiste und eine Nahkampfleiste in MelloUIs Aussehen anstelle der Swing-Timer des Spiels: jeder Schlag und Schuss neben dem Symbol deiner Waffe heruntergezählt, die Nebenhand unter der Waffenhand, die Schüsse eines Zauberstabs auf der Nahkampfleiste. Die Swing-Timer des Spiels sind ausgeschaltet, solange dies an ist, und kommen so zurück, wie du sie hattest, wenn es aus ist. Solange die Persönliche Anzeige deinen Schwung auf ihren Leisten zeigt (Schwung auf den Leisten), treten diese Balken zur Seite.", -- draft
	["Every swing and shot at a glance."] = "Jeder Schlag und Schuss auf einen Blick.", -- draft
	["Shot Bar"] = "Schussleiste", -- draft
	["The shot bar for a bow, gun, crossbow or thrown weapon while Auto Shot is on: cream, shrinking to the middle while it reloads (you can move), then red, growing from the middle while you aim: stand still, moving holds the shot back."] = "Die Schussleiste für Bogen, Schusswaffe, Armbrust oder Wurfwaffe, solange Automatischer Schuss an ist: creme, zur Mitte schrumpfend, während sie nachlädt (du kannst dich bewegen), dann rot, von der Mitte wachsend, während du zielst: Bleib stehen, Bewegung hält den Schuss zurück.", -- draft
	["Melee Bar"] = "Nahkampfleiste", -- draft
	["The melee bar: each swing of your main hand counted down, shrinking to the middle. A wand's shots (Shoot) count down on it too."] = "Die Nahkampfleiste: jeder Schlag deiner Waffenhand heruntergezählt, zur Mitte schrumpfend. Die Schüsse eines Zauberstabs (Schießen) zählen auch darauf herunter.", -- draft
	["Off Hand Bar"] = "Nebenhandleiste", -- draft
	["A thinner bar under the melee bar for your off-hand weapon's swings, while you carry one."] = "Eine dünnere Leiste unter der Nahkampfleiste für die Schläge deiner Nebenhandwaffe, solange du eine trägst.", -- draft
	["Seconds"] = "Sekunden", -- draft
	["The seconds left, past the bar's right end; on the shot bar Hold and Moving there while you aim. Off: the bars alone."] = "Die verbleibenden Sekunden hinter dem rechten Ende der Leiste; auf der Schussleiste dort „Halten“ und „Bewegung“, während du zielst. Aus: nur die Leisten.", -- draft
	["Width"] = "Breite", -- draft
	["How wide the bars are; the weapon's rim hangs left of them and the seconds right of them. Also in Edit Layout (right-click a bar there)."] = "Wie breit die Leisten sind; der Rand der Waffe hängt links davon, die Sekunden rechts davon. Auch unter „Layout bearbeiten“ (dort Rechtsklick auf eine Leiste).", -- draft
	["Height"] = "Höhe", -- draft
	["How tall the bars are; the off hand's is 60 % of it, and the weapon's rim grows with them from 15 on. Also in Edit Layout."] = "Wie hoch die Leisten sind; die der Nebenhand ist 60 % davon, und der Rand der Waffe wächst ab 15 mit. Auch unter „Layout bearbeiten“.", -- draft
	["In Combat: a bar shows in a fight once it swings or shoots, and fades out when the fight ends (the shot bar also when Auto Shot stops). Always: each bar shows while you carry a weapon for it, at rest between swings."] = "Im Kampf: Eine Leiste erscheint im Kampf, sobald sie schlägt oder schießt, und blendet aus, wenn der Kampf endet (die Schussleiste auch, wenn Automatischer Schuss endet). Immer: Jede Leiste erscheint, solange du eine Waffe dafür trägst, in Ruhe zwischen den Schlägen.", -- draft
	["In Combat"] = "Im Kampf", -- draft
	["Always"] = "Immer", -- draft
	-- PartyMarkers
	["Party Markers"] = "Gruppenmarkierungen", -- draft
	["A class medallion above every party member's friendly nameplate, with a ring in their role's colour. In the open world; inside instances the game keeps friendly nameplates to itself."] = "Ein Klassenmedaillon über der freundlichen Namensplakette jedes Gruppenmitglieds, mit einem Ring in der Farbe seiner Rolle. In der offenen Welt; in Instanzen behält das Spiel die freundlichen Namensplaketten für sich.", -- draft
	["A class medallion over every party member's head, ringed in their role's colour: the healer, found at a glance."] = "Ein Klassenmedaillon über dem Kopf jedes Gruppenmitglieds, umringt in der Farbe seiner Rolle: den Heiler auf einen Blick finden.", -- draft
	["Markers"] = "Markierungen", -- draft
	["Mark"] = "Markieren", -- draft
	["Whose nameplate gets the class medallion above the name."] = "Wessen Namensplakette das Klassenmedaillon über dem Namen bekommt.", -- draft
	["Party and raid members"] = "Gruppen- und Schlachtzugsmitglieder", -- draft
	["Every friendly player"] = "Jeder freundliche Spieler", -- draft
	["Marker Size"] = "Größe der Markierung", -- draft
	["The medallion's size above the name."] = "Die Größe des Medaillons über dem Namen.", -- draft
	["Height Above The Name"] = "Höhe über dem Namen", -- draft
	["The gap between the name and the medallion."] = "Der Abstand zwischen dem Namen und dem Medaillon.", -- draft
	["Role Ring"] = "Rollenring", -- draft
	["A coloured ring around the medallion for the member's assigned role: green healer, blue tank, red damage. Only when the group has roles set (the group finder sets them; a party can set them by hand)."] = "Ein farbiger Ring um das Medaillon für die zugewiesene Rolle des Mitglieds: grün Heiler, blau Tank, rot Schaden. Nur wenn die Gruppe Rollen gesetzt hat (die Dungeonbrowser setzt sie; eine Gruppe kann sie von Hand setzen).", -- draft
	["Open world only: inside instances the game keeps friendly nameplates to itself"] = "Nur in der offenen Welt: in Instanzen behält das Spiel die freundlichen Namensplaketten für sich", -- draft
	-- Sparkles
	["Loot Sparkles"] = "Beutefunkeln", -- draft
	["The game's sparkle on quest items you can loot, kept on through its graphics presets, and golden glints over the ore veins and herbs you walk up to: dim out of reach, bright in reach, grey when your skill is too low. The game settings it needs come back as you had them when it is off."] = "Das Funkeln des Spiels auf plünderbaren Questgegenständen, durch seine Grafikvorgaben hindurch beibehalten, und goldene Glanzlichter über den Erzadern und Kräutern, auf die du zugehst: matt außer Reichweite, hell in Reichweite, grau, wenn deine Fertigkeit zu niedrig ist. Die nötigen Spieleinstellungen kommen so zurück, wie du sie hattest, wenn es aus ist.", -- draft
	["What you can loot, at a glance."] = "Was du plündern kannst, auf einen Blick.", -- draft
	["Quest Item Sparkles"] = "Funkeln auf Questgegenständen", -- draft
	["Keeps the game's sparkle on quest items you can loot. It needs the game's outline mode off, which its graphics presets switch back on: held while this is on, given back as you had it when off. Switching this off takes the sparkles away after the next game restart (the client's own; /reload is not enough)."] = "Behält das Funkeln des Spiels auf plünderbaren Questgegenständen. Es braucht den Konturmodus des Spiels aus, den seine Grafikvorgaben wieder einschalten: gehalten, solange dies an ist, zurückgegeben, wie du es hattest, wenn es aus ist. Ausschalten nimmt das Funkeln erst nach dem nächsten Neustart des Spiels weg (das des Clients selbst; /reload genügt nicht).", -- draft
	["Ore Veins"] = "Erzadern", -- draft
	["Golden glints over the ore vein you walk up to (the game's soft targeting picks the nearest one, within about 15 yards): dim out of reach, bright once you can mine it, grey when your skill is too low."] = "Goldene Glanzlichter über der Erzader, auf die du zugehst (die weiche Zielerfassung des Spiels wählt die nächste, innerhalb von etwa 15 Metern): matt außer Reichweite, hell, sobald du sie abbauen kannst, grau, wenn deine Fertigkeit zu niedrig ist.", -- draft
	["Herbs"] = "Kräuter", -- draft
	["The same glints over the herb you walk up to."] = "Dieselben Glanzlichter über dem Kraut, auf das du zugehst.", -- draft
	["Quest Objects"] = "Questobjekte", -- draft
	["The same glints over a quest object you walk up to. Off by default: the game's own sparkle (Quest Item Sparkles) already marks most of them."] = "Dieselben Glanzlichter über einem Questobjekt, auf das du zugehst. Standardmäßig aus: Das Funkeln des Spiels (Funkeln auf Questgegenständen) markiert die meisten schon.", -- draft
	-- CustomSounds
	["Custom Sounds"] = "Eigene Sounds", -- draft
	["The interface's sounds replaced by the custom library: iron, leather, parchment and stone for clicks, windows, bags, gear, vendors, whispers and the group finder."] = "Die Klänge der Oberfläche durch die eigene Bibliothek ersetzt: Eisen, Leder, Pergament und Stein für Klicks, Fenster, Taschen, Ausrüstung, Händler, Flüstern und die Dungeonbrowser.", -- draft
	["Iron, leather, parchment and stone. Every click, page, pouch and buckle of the interface, re-recorded."] = "Eisen, Leder, Pergament und Stein. Jeder Klick, jede Seite, jeder Beutel und jede Schnalle der Oberfläche, neu aufgenommen.", -- draft
	["Sounds"] = "Klänge", -- draft
	["Clicks"] = "Klicks", -- draft
	["Buttons, checkboxes, tabs and scroll arrows: light clicks, a heavy one for Okay/Accept, a latch releasing for Cancel, Quit and abandoning a quest."] = "Schaltflächen, Kontrollkästchen, Reiter und Scrollpfeile: leichte Klicks, ein schwerer für Okay/Annehmen, ein lösender Riegel für Abbrechen, Beenden und das Abbrechen einer Quest.", -- draft
	["Windows"] = "Fenster", -- draft
	["A page turn when the character sheet, spell book, quest log or main menu opens, a latch when they close; the spell book's page turns; a quest giver's list and Decline; the bags as a leather pouch opening and closing."] = "Ein Umblättern, wenn Charakterfenster, Zauberbuch, Questlog oder Hauptmenü öffnen, ein Riegel, wenn sie schließen; das Umblättern im Zauberbuch; die Liste eines Questgebers und Ablehnen; die Taschen als Lederbeutel, der sich öffnet und schließt.", -- draft
	["Inventory"] = "Inventar", -- draft
	["An item picked up, moved between slots, put down or looted; a rare or better item has its own sound. Silences the game's own pick-up and put-down sounds (the Equipment and Vendor sounds rely on that, and play only while this is on)."] = "Ein Gegenstand aufgenommen, zwischen Plätzen verschoben, abgelegt oder geplündert; ein seltener oder besserer Gegenstand hat einen eigenen Klang. Stellt die Aufnahme- und Ablegeklänge des Spiels stumm (die Klänge für Ausrüstung und Händler bauen darauf und spielen nur, solange dies an ist).", -- draft
	["Equipment"] = "Ausrüstung", -- draft
	["Buckles and plate for armour, a steel slide for weapons, jewellery ticks for rings, necks and trinkets; straps loosening when something is taken off."] = "Schnallen und Platten für Rüstung, ein Stahlgleiten für Waffen, Schmuckklicken für Ringe, Hälse und Schmuckstücke; sich lockernde Riemen, wenn etwas abgelegt wird.", -- draft
	["Coins on the counter when buying, coins into the pouch when selling (the automatic grey sale too)."] = "Münzen auf dem Tresen beim Kaufen, Münzen in den Beutel beim Verkaufen (auch beim automatischen Verkauf von Grauem).", -- draft
	["Social"] = "Soziales", -- draft
	["A note under the door for a whisper, two knocks for a group invite."] = "Ein Zettel unter der Tür für ein Flüstern, zweimal Klopfen für eine Gruppeneinladung.", -- draft
	["Group Finder"] = "Dungeonbrowser", -- draft
	["The ledger for entering a queue or applying to a listing, a strike-through for leaving it, the bell for a group that is ready and for a ready check."] = "Das Hauptbuch beim Anmelden in einer Warteschlange oder beim Bewerben auf einen Eintrag, ein Durchstreichen beim Verlassen, die Glocke für eine bereite Gruppe und für einen Bereitschaftscheck.", -- draft
	["The workbench when an item is crafted."] = "Die Werkbank, wenn ein Gegenstand hergestellt wird.", -- draft
	["Quests"] = "Quests", -- draft
	["The mechanism engaging when a quest is turned in."] = "Der einrastende Mechanismus, wenn eine Quest abgegeben wird.", -- draft
	["Errors"] = "Fehler", -- draft
	["A muted knock for the game's red error messages (\"You can't do that yet\"), at most one every half second; none for a message Error Messages hides."] = "Ein gedämpftes Klopfen für die roten Fehlermeldungen des Spiels („Das könnt Ihr noch nicht.“), höchstens eins pro halbe Sekunde; keins für eine Meldung, die „Fehlermeldungen“ ausblendet.", -- draft
	["Targets"] = "Ziele", -- draft
	["An iron sight catching when a target is selected, a latch releasing when it is lost."] = "Ein einrastendes Eisenvisier, wenn ein Ziel gewählt wird, ein lösender Riegel, wenn es verloren geht.", -- draft
	["A seal struck into the record when you level."] = "Ein Siegel, das beim Stufenaufstieg in die Chronik geschlagen wird.", -- draft
	["Loot Coins"] = "Beutemünzen", -- draft
	["Coins into the pouch when money is looted."] = "Münzen in den Beutel, wenn Geld geplündert wird.", -- draft
	["Spell Icons"] = "Zaubersymbole", -- draft
	["A page lifting when a spell, macro or ability is dragged, the slot latching when it is placed."] = "Eine sich hebende Seite, wenn ein Zauber, Makro oder eine Fähigkeit gezogen wird, ein einrastender Platz, wenn er abgelegt wird.", -- draft
	["Map Ping"] = "Kartensignal", -- draft
	["An iron pin into the parchment for a minimap ping."] = "Eine Eisennadel ins Pergament für ein Signal auf der Minikarte.", -- draft
	["Scroll Wheel"] = "Mausrad", -- draft
	["One cog notch per mouse-wheel step on any list, window or the chat. The game has no wheel sound; this is an addition."] = "Eine Zahnradraste pro Mausradschritt in jeder Liste, jedem Fenster oder dem Chat. Das Spiel hat keinen Mausradklang; dies ist eine Ergänzung.", -- draft
	["Hover Ticks"] = "Ticks beim Darüberfahren", -- draft
	["A tiny tick when the mouse reaches a button. The game has no hover sound; this is an addition."] = "Ein winziger Tick, wenn die Maus eine Schaltfläche erreicht. Das Spiel hat keinen Klang dafür; dies ist eine Ergänzung.", -- draft
