	["Party Grows"] = "Gruppe wächst", -- draft
	["Which way the party's frames line up from where you placed them."] = "In welche Richtung sich die Fenster der Gruppe von dort aus aufreihen, wo du sie platziert hast.", -- draft
	["Party Order"] = "Reihenfolge der Gruppe", -- draft
	["The order of the party's frames: tanks, then healers, then damage; the game's group order; or by name."] = "Die Reihenfolge der Fenster der Gruppe: Tanks, dann Heiler, dann Schaden; die Gruppenreihenfolge des Spiels; oder nach Name.", -- draft
