	["Raid Spacing"] = "Schlachtzugsabstand", -- draft
	["The room between two of the raid's frames in a column (or a row). Also on the raid's plate in Edit Layout (right-click it)."] = "Der Platz zwischen zwei Fenstern des Schlachtzugs in einer Spalte (oder Reihe). Auch auf dem Schild des Schlachtzugs unter „Layout bearbeiten“ (Rechtsklick darauf).", -- draft
