	["Smooth Bars"] = "Sanfte Balken", -- draft
	["The bars glide to a new value instead of jumping."] = "Die Balken gleiten zu einem neuen Wert, statt zu springen.", -- draft
	["What lies behind the health bar: a flat colour (Background Colour), one of MelloUI's backgrounds (stone, concrete, parchment, the dark gradients...), or none."] = "Was hinter dem Gesundheitsbalken liegt: eine flache Farbe (Hintergrundfarbe), einer von MelloUIs Hintergründen (Stein, Beton, Pergament, die dunklen Verläufe ...) oder keiner.", -- draft
	["Flat colour"] = "Flache Farbe", -- draft
	["Background Colour"] = "Hintergrundfarbe", -- draft
