	["Missing Health"] = "Fehlende Gesundheit", -- draft
	["The part of the bar a member has lost, in a colour of its own: yours, their class colour, or by health."] = "Der Teil des Balkens, den ein Mitglied verloren hat, in einer eigenen Farbe: deiner, seiner Klassenfarbe oder nach Gesundheit.", -- draft
	["By Health"] = "Nach Gesundheit", -- draft
