	["Healers"] = "Heiler", -- draft
	["Everyone"] = "Alle", -- draft
	["Your Power Bar While Solo"] = "Dein Ressourcenbalken allein", -- draft
	["Your own power bar while you play solo, whatever your role."] = "Dein eigener Ressourcenbalken, solange du allein spielst, unabhängig von deiner Rolle.", -- draft
