	["Name Colour"] = "Namensfarbe", -- draft
	["The name's colour: white, the member's class colour, or one of yours."] = "Die Farbe des Namens: weiß, die Klassenfarbe des Mitglieds oder eine deiner Farben.", -- draft
	["White"] = "Weiß", -- draft
	["My Name Colour"] = "Meine Namensfarbe", -- draft
	["The name's colour with My Colour."] = "Die Farbe des Namens mit „Meine Farbe“.", -- draft
