	["Health Text"] = "Gesundheitstext", -- draft
	["The health shown as text: its percent, the current health, or how much is missing."] = "Die Gesundheit als Text: ihr Prozentwert, die aktuelle Gesundheit oder wie viel fehlt.", -- draft
