	["The face of the names on your party and raid frames. Shared: the Interface text's face (Look > Fonts)."] = "Die Schrift der Namen auf deinen Gruppen- und Schlachtzugsfenstern. Gemeinsam: die Schrift des Oberflächentexts (Aussehen > Schriften).", -- draft
	["Health Text Font"] = "Schrift des Gesundheitstexts", -- draft
	["The face of the health text on your party and raid frames, and of the Dead, Ghost and Offline words. Shared: the Interface text's face (Look > Fonts)."] = "Die Schrift des Gesundheitstexts auf deinen Gruppen- und Schlachtzugsfenstern und der Wörter Tot, Geist und Offline. Gemeinsam: die Schrift des Oberflächentexts (Aussehen > Schriften).", -- draft
	["Indicator Numbers Font"] = "Schrift der Anzeigenzahlen", -- draft
